function cap(s){ return s.charAt(0).toUpperCase()+s.slice(1); }
function clean(s){
  s=String(s||'').replace(/[\uE000\uE001]/g,'').replace(/\s+/g,' ').trim();
  // Длинное «—» является штатным символом оригинала: оно используется
  // как разделитель двух групп и как заглушка пустого поля обращения.
  // Короткий дефис и среднее тире не являются частью схем генератора,
  // но могут случайно остаться как разделитель-артефакт — однако только
  // если они уже отделены пробелами с обеих сторон. Дефис, приклеенный
  // к буквам («чуть-чуть», «прямо-таки»), — это часть самого слова и не
  // должен вырезаться.
  s=s.replace(/\s+[–-]\s+/gu,' ');
  s=s.replace(/\s*—\s*/gu,' — ');
return s.trim();
}

function shuffle(a){
  for(let i=a.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); [a[i],a[j]]=[a[j],a[i]]; }
  return a;
}

function choose(arr, localUsed, batchUsed, diversityOverride, ctx){
  const diversity = diversityOverride == null
    ? Number(document.querySelector('#diversity').value) / 100
    : diversityOverride;
  if(!arr || !arr.length) return '';

  // 0% = чистый рандом. Никаких анти-повторов: генератор берёт слово
  // напрямую из исходного пула, как старый генератор мог делать.
  if(diversity <= 0) return pick(arr);

  const local = localUsed || new Set();
  const batch = batchUsed || new Set();

  // Разнообразие теперь не означает «запретить всё уже использованное».
  // Это плавная вероятность штрафа:
  //   0%   — полностью случайно;
  //   50%  — мягкий анти-повтор, нормальный режим;
  //   100% — жёсткое исключение уже использованного до исчерпания пула.
  // Так повтор слова в одной фразе возможен, но на 50% не превращается
  // в постоянное дублирование.
  const freshLocal = arr.filter(x=>!local.has(x));
  const freshBatch = arr.filter(x=>!batch.has(x));

  if(diversity >= 1){
    // Сначала слово, которое не встречалось ни в текущей фразе, ни в пачке.
    const batchFreshLocal=freshLocal.filter(x=>!batch.has(x));
    if(batchFreshLocal.length) return pick(batchFreshLocal);
    // Если локально свободных слов больше нет, допускаем слово, ещё не
    // встречавшееся в пачке. Повтор возможен только после реального
    // исчерпания конкретного пула.
    if(freshLocal.length) return pick(freshLocal);
    const freshGlobal=arr.filter(x=>!batch.has(x));
    if(freshGlobal.length) return pick(freshGlobal);
    return pick(arr);
  }

  // Вес уже использованного слова уменьшается постепенно. При 50%:
  // повтор внутри текущей фразы получает примерно 58% обычного веса,
  // повтор из предыдущих строк — примерно 68%. При 100% эти веса
  // обнуляются через ветку выше.
  const localPenalty = Math.max(0.035, 1 - 1.75*diversity);
  const batchPenalty = Math.max(0.06, 1 - 1.45*diversity);
  const freq = ctx.freq || (ctx.freq = new Map());
  const weighted = arr.map(x=>{
    const n=freq.get(x)||0;
    // Повтор одного и того же слова несколько раз в пачке получает
    // дополнительный плавный штраф. Это особенно важно для маленьких
    // специализированных пулов вроде role-слов: 50% не должен превращаться
    // в «пиздососка» через каждые две строки.
    const repeatPenalty = n>0 ? Math.pow(0.62, Math.min(n,4)) : 1;
    const w=(local.has(x) ? localPenalty : (batch.has(x) ? batchPenalty : 1))*repeatPenalty;
    return {x,w};
  });
  const total=weighted.reduce((sum,z)=>sum+z.w,0);
  let r=Math.random()*total;
  for(const z of weighted){
    r-=z.w;
    if(r<=0) return z.x;
  }
  return weighted[weighted.length-1].x;
}

// 0.810: реестр схем должен быть доступен schemePick().
// Раньше SCHEME_META был объявлен внутри makePhrase(), поэтому глобальная
// schemePick() получала ReferenceError при любой адресной/хаос-схеме.
const SCHEME_META = Object.freeze({
  rare: new Set(['s12','s13','s14','m16','l15']),
  role: new Set([
    'c2','c5','c6','c8','c9','c10',
    'ct2','ct4','ct6',
    't3','t5','t6','t18','t19','t20','t22','t24','t25','t26',
    't27','t28','t29','t30','t31','t32','t33','t34'
  ]),
  dash: new Set([
    'c1','c2','c3','c4','c5','c6','c7','c8','c9','c10',
    'ct1','ct2','ct3','ct4','ct5','ct6',
    't14','t15','t16','t17','t18','t19','t20',
    't21','t22','t23','t24','t25','t26','t28','t29','t31','t32','t33','t34'
  ]),
  targetClassic: new Set(['t1','t2','t3','t4','t5','t6','t7','t8','t9']),
  targetTail: new Set(['t12','t13','t14','t15','t16','t17','t18','t19','t20','t21','t22','t23','t24','t25','t26','t27','t28','t29','t30','t31','t32','t33','t34'])
});

function schemePick(pool, key, ctx, diversity){
  if(!pool.length) return null;

  // Взвешивание теперь определяется метаданными именно активного пула.
  // Никаких ссылок на старые s*/m*/l*-ID для c*/ct*/t*-схем.
  const rare=pool.filter(x=>SCHEME_META.rare.has(x.id));
  const ordinary=pool.filter(x=>!SCHEME_META.rare.has(x.id));
  let active=pool;
  if(rare.length && ordinary.length) active=chance(0.045)?rare:ordinary;

  function weight(x){
    let w=1;
    const isRole=SCHEME_META.role.has(x.id);
    const isDash=SCHEME_META.dash.has(x.id);
    if(isRole) w*=0.72;
    else if(isDash) w*=0.55;

    if(key==='target'){
      if(SCHEME_META.targetClassic.has(x.id)) w*=1.16;
      if(SCHEME_META.targetTail.has(x.id)) w*=0.96;
    }
    return w;
  }

  function weightedPick(list){
    const weighted=list.map(x=>({x,w:weight(x)}));
    const total=weighted.reduce((a,b)=>a+b.w,0);
    let r=Math.random()*total;
    for(const z of weighted){ r-=z.w; if(r<=0) return z.x; }
    return weighted[weighted.length-1].x;
  }

  if(diversity<=0) return weightedPick(active);

  const fresh=active.filter(x=>!ctx.schemes.has(x.id));
  if(!fresh.length) return weightedPick(active);
  if(diversity>=1) return weightedPick(fresh);
  if(chance(diversity)) return weightedPick(fresh);
  return weightedPick(active);
}
function adjectiveForGender(word, gender){
  if(gender !== 'female') return word;
  const exactFemale = ADJ_FEMALE[word];
  if(exactFemale) return exactFemale;

  let w = String(word || '');
  const rules = [
    [/нувшийся$/u,'нувшаяся'],[/ившийся$/u,'ившаяся'],[/ывшийся$/u,'ывшаяся'],[/авшийся$/u,'авшаяся'],[/евшийся$/u,'евшаяся'],[/явшийся$/u,'явшаяся'],
    [/ующийся$/u,'ующаяся'],[/ающийся$/u,'ающаяся'],[/яющийся$/u,'яющаяся'],[/ущийся$/u,'ущаяся'],[/ящийся$/u,'ящаяся'],[/ющийся$/u,'ющаяся'],
    [/нувший$/u,'нувшая'],[/ивший$/u,'ившая'],[/ывший$/u,'ывшая'],[/авший$/u,'авшая'],[/евший$/u,'евшая'],[/явший$/u,'явшая'],
    [/ующий$/u,'ующая'],[/ающий$/u,'ающая'],[/яющий$/u,'яющая'],[/ущий$/u,'ущая'],[/ящий$/u,'ящая'],[/ющий$/u,'ющая'],
    [/ированный$/u,'ированная'],[/ованный$/u,'ованная'],[/еванный$/u,'еванная'],[/янный$/u,'янная'],[/анный$/u,'анная'],[/енный$/u,'енная'],[/ённый$/u,'ённая'],
    [/ческий$/u,'ческая'],[/ский$/u,'ская'],[/цкий$/u,'цкая'],[/гий$/u,'гая'],[/кий$/u,'кая'],[/ний$/u,'няя'],[/хий$/u,'хая'],[/чий$/u,'чья'],[/ший$/u,'шая'],[/жий$/u,'жая'],
    [/ый$/u,'ая'],[/ой$/u,'ая'],[/ий$/u,'ая']
  ];
  for(const [rx,repl] of rules){ if(rx.test(w)) return w.replace(rx,repl); }
  return w;
}

