function targetWordValue(){ const el=document.querySelector('#targetWord'); return el ? String(el.value||'').trim() : ''; }

function makePhrase(gender, batchCtx, allowTarget=true){
  const ctx = batchCtx || {words:new Set(),schemes:new Set(),advs:new Set(),freq:new Map(),roleRecent:[],compoundFreq:new Map()};
  const used = new Set();
  const chaos = gender === 'chaos';
  // Цель читается непосредственно в момент генерации каждой фразы.
  // Поэтому обычные режимы и режим «Текст» используют одно и то же поле.
  const target = allowTarget ? targetWordValue() : '';
  // «Разное» = один род на всю фразу, выбираемый для каждой строки.
  // «Хаос» = род выбирается заново для независимых именных групп внутри
  // одной строки. Поэтому «Хаос» намеренно может дать мужскую первую группу
  // и женскую вторую, чего в «Разное» быть не должно.
  // Поле «Обматерить» никогда не определяет род.
  const phraseGender = chaos ? null : gender;
  const groupGender=(forced)=>{
    if(forced==='male' || forced==='female') return forced;
    return chaos ? (chance(.5) ? 'male' : 'female') : phraseGender;
  };
  const diversity = Number(document.querySelector('#diversity').value)/100;
  const compoundEnabled = !!document.querySelector('#compoundMode')?.checked;

  // Составной режим полностью изолирован от основной генерации.
  // «султан» и «говно» теперь находятся в основной мужской базе DB.
  // При включённой галочке дополнительно разрешены новые искусственные
  // составные слова: числительное + приставка + 2 матерных корня.
  // Составные слова: отдельный генератор, полностью необязательные
  // компоненты. Он не вмешивается в обычный выбор слов и включается только
  // галочкой «Составные слова».
  // 0.828: составные слова строятся не из произвольных обрубков, а из
  // морфемных основ с контролем совместимости. Это сохраняет старошкольный
  // абсурд, но убирает формы вроде «гандговноищ» и «пидрсосоая».
  // Основа хранится уже в пригодной для сложения форме. Не смешиваем
  // несовместимые обрубки вроде «ганд» + «говн» или «сосо» + «ая».
  // Для прилагательных отдельный набор готовых основ. Они не заканчиваются
  // на случайное -о перед суффиксом, поэтому не рождают «...оий»/«...оый».
  const C_CLASSIC_ADJ=['троедвупиздый','хуедвупиздый','малопидохуий','сверхпиздожопый','двухмудохуевый'];
  const C_CLASSIC_NOUN=['лихомелкомудник','хуедвупиздник','пиздожопник','мудохуярь','говнопиздец'];

  // 0.828: составные слова строятся моделями, а не свободным декартовым
  // произведением «приставка × корень × суффикс». Каждый набор ниже уже
  // представляет допустимый старошкольный тип.
  const C_ADJ_MODELS=[
    {stem:'хуепизд',suffixes:['ый','истый'],prefixes:['дву','три','сверх']},
    {stem:'хуебляд',suffixes:['ый','истый'],prefixes:['три','трёх','сверх']},
    {stem:'хуежоп',suffixes:['ый','ой'],prefixes:['дву','три','мало']},
    {stem:'пиздожоп',suffixes:['ый','ой','истый'],prefixes:['дву','три','сверх']},
    {stem:'пиздобляд',suffixes:['ый','истый'],prefixes:['три','трёх','мало']},
    {stem:'мудобляд',suffixes:['ый','истый'],prefixes:['дву','три','трёх']},
    {stem:'мудопизд',suffixes:['ый','ый'],prefixes:['дву','три','сверх']},
    {stem:'говнопизд',suffixes:['ый','истый'],prefixes:['три','трёх','мало']},
    {stem:'говножоп',suffixes:['ый','ой'],prefixes:['дву','три','сверх']},
    {stem:'блядожоп',suffixes:['ый','ой','истый'],prefixes:['дву','три','сверх']},
    {stem:'залупоху',suffixes:['евый','истый'],prefixes:['дву','три','сверх']},
    {stem:'членоговн',suffixes:['ый','истый'],prefixes:['три','трёх','сверх']},
    {stem:'пидопизд',suffixes:['ый','истый'],prefixes:['дву','три','сверх']},
    {stem:'пидосос',suffixes:['ый','истый'],prefixes:['дву','три','сверх']},
    {stem:'сучепидр',suffixes:['ый','истый'],prefixes:['дву','три','сверх']},
    {stem:'гандоху',suffixes:['евый','истый'],prefixes:['дву','три','мало']},
    {stem:'дрочебляд',suffixes:['ый','истый'],prefixes:['три','трёх','сверх']},
    {stem:'трахопизд',suffixes:['ый','истый'],prefixes:['дву','три','сверх']},
    {stem:'пердожоп',suffixes:['ый','ой'],prefixes:['дву','три','мало']},
    {stem:'сракопизд',suffixes:['ый','истый'],prefixes:['дву','три','сверх']},
    {stem:'мозгопизд',suffixes:['ый','истый'],prefixes:['дву','три','сверх']},
    {stem:'еблосос',suffixes:['ый','истый'],prefixes:['дву','три','сверх']},
    {stem:'пиздосос',suffixes:['ый','истый'],prefixes:['дву','три','сверх']}
  ];
  const C_NOUN_MODELS=[
    {stem:'хуепизд',suffixes:['ник','арь'],prefixes:['дву','три','сверх']},
    {stem:'хуебляд',suffixes:['ник','арь'],prefixes:['три','трёх','сверх']},
    {stem:'хуежоп',suffixes:['ник','ец'],prefixes:['дву','три','мало']},
    {stem:'пиздожоп',suffixes:['ник','арь'],prefixes:['дву','три','сверх']},
    {stem:'пиздобляд',suffixes:['ник','арь'],prefixes:['три','трёх','мало']},
    {stem:'мудобляд',suffixes:['ник','арь'],prefixes:['дву','три','трёх']},
    {stem:'говнопизд',suffixes:['ник','арь','ец'],prefixes:['три','трёх','мало']},
    {stem:'говножоп',suffixes:['ник','ец'],prefixes:['дву','три','сверх']},
    {stem:'блядожоп',suffixes:['ник','арь'],prefixes:['дву','три','сверх']},
    {stem:'залупохуй',suffixes:['ник','арь'],prefixes:['дву','три','сверх']},
    {stem:'членоговн',suffixes:['ник','арь'],prefixes:['три','трёх','сверх']},
    {stem:'пидопизд',suffixes:['ник','арь'],prefixes:['дву','три','сверх']},
    {stem:'пидосос',suffixes:['ник','арь'],prefixes:['дву','три','сверх']},
    {stem:'сучепидр',suffixes:['ник','арь'],prefixes:['дву','три','сверх']},
    {stem:'гандохуй',suffixes:['ник','арь'],prefixes:['дву','три','мало']},
    {stem:'дрочебляд',suffixes:['ник','арь'],prefixes:['три','трёх','сверх']},
    {stem:'трахопизд',suffixes:['ник','арь'],prefixes:['дву','три','сверх']},
    {stem:'пердожоп',suffixes:['ник','ец'],prefixes:['дву','три','мало']},
    {stem:'сракопизд',suffixes:['ник','арь'],prefixes:['дву','три','сверх']},
    {stem:'мозгопизд',suffixes:['ник','арь'],prefixes:['дву','три','сверх']},
    {stem:'еблосос',suffixes:['ник','арь'],prefixes:['дву','три','сверх']},
    {stem:'пиздосос',suffixes:['ник','арь'],prefixes:['дву','три','сверх']}
  ];
  const C_JOINED_ADJ=['хуепиздовый','хуедвупиздый','пиздожопистый','мудохуевый','говнопиздый','сучепиздый'];
  const C_JOINED_NOUN=['лихомелкомудник','хуедвупиздник','пиздожопник','мудохуярь','говнопиздец'];
  const pickArr=a=>a[Math.floor(Math.random()*a.length)];

  function compoundAdjectiveGender(wordValue,g){
    let w=String(wordValue||'').toLowerCase();
    if(g!=='female') return w;
    if(/(ая|яя|уя|юя|ная|ская|истая|ливая|ющая|анная)$/u.test(w)) return w;
    if(/хуий$/u.test(w)) return w.replace(/хуий$/u,'хуйная');
    if(/хуевый$/u.test(w)) return w.replace(/хуевый$/u,'хуевая');
    if(/двупиздый$/u.test(w)) return w.replace(/ый$/u,'ая');
    if(/пиздый$/u.test(w)) return w.replace(/ый$/u,'ая');
    if(/ский$/u.test(w)) return w.replace(/ский$/u,'ская');
    if(/истый$/u.test(w)) return w.replace(/истый$/u,'истая');
    if(/ливый$/u.test(w)) return w.replace(/ливый$/u,'ливая');
    if(/ющийся$/u.test(w)) return w.replace(/ющийся$/u,'ющаяся');
    if(/ющий$/u.test(w)) return w.replace(/ющий$/u,'ющая');
    if(/анный$/u.test(w)) return w.replace(/анный$/u,'анная');
    if(/ый$/u.test(w)) return w.replace(/ый$/u,'ая');
    if(/ой$/u.test(w)) return w.replace(/ой$/u,'ая');
    if(/ий$/u.test(w)) return w.replace(/ий$/u,'ая');
    return w;
  }

  function compoundNounGender(wordValue,g){
    let w=String(wordValue||'').toLowerCase();
    if(g!=='female') return w;
    if(/(ница|ица|чица|щица|арка|унья|ачка|ячка|оида|ышка|ка)$/u.test(w)) return w;
    if(/ник$/u.test(w)) return w.replace(/ник$/u,'ница');
    if(/ец$/u.test(w)) return w.replace(/ец$/u,'ица');
    if(/арь$/u.test(w)) return w.replace(/арь$/u,'арка');
    return w;
  }

  // 0.834: составные слова переработаны по образцу старого генератора.
  // В оригинальной манере составное слово НЕ обязано существовать в словаре:
  // берутся основы словаря и склеиваются в новую лексему. Поэтому здесь больше
  // нет закрытого набора из заранее придуманных «хуедвупиздый» и т.п.
  // Компоненты для композита всегда происходят из DB, а результат проверяется
  // на отсутствие в словаре.
  const C_CLASSIC_ALL=new Set([...C_CLASSIC_ADJ,...C_CLASSIC_NOUN]);
  const COMPOUND_POOL_CACHE={adj:null,noun:null};
  const COMPOUND_SOURCE_CACHE={nouns:null,adjs:null,dict:null};

  function compoundSourceData(){
    if(COMPOUND_SOURCE_CACHE.dict) return COMPOUND_SOURCE_CACHE;
    const nouns=[...(DB.male||[]),...(DB.female||[])].filter(Boolean);
    const adjs=[...(DB.adj||[])].filter(Boolean);
    const uniq=a=>[...new Set(a.map(x=>String(x).toLowerCase()).filter(Boolean))];
    COMPOUND_SOURCE_CACHE.nouns=uniq(nouns);
    COMPOUND_SOURCE_CACHE.adjs=uniq(adjs);
    COMPOUND_SOURCE_CACHE.dict=new Set([...COMPOUND_SOURCE_CACHE.nouns,...COMPOUND_SOURCE_CACHE.adjs]);
    return COMPOUND_SOURCE_CACHE;
  }

  function nounCompoundStem(w){
    let x=String(w||'').toLowerCase();
    // Сначала убираем характерные словообразовательные окончания, чтобы
    // «пиздец» -> «пизд», «долбоёб» -> «долбоёб», «мудила» -> «мудил».
    x=x.replace(/(?:ниц|щиц|чиц|щик|ник|чик|ец|арь|ун|ак|як|ок|ек|ик|онок|ёныш|ыш|ышек)$/u,'');
    x=x.replace(/[аяоеёьи]$/u,'');
    if(x.length<3) return '';
    return x;
  }

  function adjCompoundStem(w){
    let x=String(w||'').toLowerCase();
    x=x.replace(/(?:ский|цкий)$/u,'');
    x=x.replace(/(?:истый|оватый|евый|ливый|чивый|анный|енный|ённый|ованный|ированный)$/u,'');
    x=x.replace(/(?:ый|ий|ой)$/u,'');
    if(x.length<3) return '';
    return x;
  }

  function adjToAdverbStem(w){
    const x=adjCompoundStem(w);
    if(!x) return '';
    return x+'о';
  }

  function randomSourceStem(kind){
    const d=compoundSourceData();
    if(kind==='adj'){
      const w=pickArr(d.adjs), stem=adjCompoundStem(w);
      return {stem,source:w};
    }
    const w=pickArr(d.nouns), stem=nounCompoundStem(w);
    return {stem,source:w};
  }

  const COMPOUND_ROOT_RE=/хуяр|хуепл[её]т|хуй|пизд|бляд|муд|говн|жоп|срак|залуп|ганд|манд|суч|дроч|трах|перд|сос|сран|кал|долб|пидор|пидр|член|сперм|дрист|морда|грыз|блуд|еб|ёб/giu;
  const COMPOUND_ROOT_CACHE={obscene:null,modifiers:null,dict:null};

  function compoundRootData(){
    if(COMPOUND_ROOT_CACHE.obscene) return COMPOUND_ROOT_CACHE;
    const d=compoundSourceData();
    const roots=new Set();
    for(const w of d.nouns){
      const m=String(w).match(COMPOUND_ROOT_RE);
      if(m){
        const r=m[0].toLowerCase();
        if(r.length>=3) roots.add(r);
      }
    }
    // Несколько корней могут встречаться только внутри длинных слов, но они
    // всё равно являются словарными материалами для старой манеры склейки.
    COMPOUND_ROOT_CACHE.obscene=[...roots].filter(x=>x.length>=3&&x.length<=8);
    const mods=d.adjs.filter(w=>/^[а-яё]{4,10}(?:ый|ий|ой)$/iu.test(w));
    COMPOUND_ROOT_CACHE.modifiers=[...new Set(mods)];
    COMPOUND_ROOT_CACHE.dict=d.dict;
    return COMPOUND_ROOT_CACHE;
  }

  function rootToStem(root){
    let x=String(root||'');
    if(/(?:еб|ёб)$/u.test(x)) return x;
    return x;
  }

  function modifierToAdverb(w){
    let x=String(w||'').toLowerCase().replace(/(?:ый|ий|ой)$/u,'');
    return x+'о';
  }

  function normalizeCompoundRoot(root){
    let x=String(root||'').toLowerCase();
    // «хуй» в старых склейках обычно переходит в основу «хуе-»;
    // отдельное -й перед прилагательным окончанием даёт технические формы
    // вроде «дристохуйий».
    if(x==='хуй') x='хуе';
    else if(/й$/u.test(x) && x.length>3) x=x.slice(0,-1);
    // Не тащим в склейку случайные словоизменительные хвосты из словаря:
    // «морда + ый» превращалось в очевидно сломанное «мордаый».
    x=x.replace(/(?:ский|цкий|ный|ный|истый|оватый|евый|ливый|чивый|анный|енный|ённый|ованный|ированный|ящий|ющий|ющийся|шийся|вший)$/u,'');
    if(/[аяоеё]$/u.test(x) && x.length>4) x=x.slice(0,-1);
    return x;
  }

  // 0.914: составные слова строятся из реальных словарных источников,
  // но не из случайного куска любого слова. Сначала извлекается одна
  // узнаваемая матерная основа из конкретного элемента DB, затем основы
  // соединяются по ограниченному числу старых схем.
  // 0.915: сложные составные строятся по моделям, замеченным в старых
  // генерациях: качественная основа + матерная основа + смысловой хвост.
  // Это намеренно не морфологический словарь: цель — узнаваемая старая
  // «склейка», но без технических окончаний вроде «хуйый».
  // 0.916 patch core (embedded in 0.915 file for replacement): complex forms
  // are built from old-style compound fragments rather than arbitrary dictionary
  // substrings. These fragments mirror the shapes visible in the reference captures.
  // 0.917: reference-shaped compound lexemes. Instead of free random
  // concatenation, use attested shapes from the supplied captures as templates,
  // then mutate only one slot. This keeps the old generator's «new word» feel
  // without producing arbitrary technical strings.
  // 0.920: complex compounds use compatible slots. Each slot has a small
  // family of roots observed in the captures, so variation changes the word
  // while preserving its old-school phonetic shape.
  const REF_COMPLEX_ADJ=[
    {a:['мудо','манда','блядo'],b:['манда','пидо','опиздо'],c:['пизд','хуй','хуяр'],e:['ый','ий']},
    {a:['суче','низко'],b:['долбо','мудо','пидо'],c:['ног','хер'],e:['ий','ой']},
    {a:['мандо','блядo','пидо'],b:['блядo','суче'],c:['гондон','пизд','хер'],e:['ный']},
    {a:['жирно','толстомелко','косо'],b:['косо','мелко'],c:['хуяр','пизд'],e:['енный']},
    {a:['ебло','малоопиздо','опиздо'],b:['опиздо','мало'],c:['хер','пизд','грыз'],e:['ый','ий']},
    {a:['свино','пидо'],b:['свино','блядo'],c:['ёб','хер'],e:['анный']},
    {a:['ското','пидо'],b:['хуйл','хуе'],c:['ёб','грыз'],e:['ый','ий']},
    {a:['мало','малопидо','малоопиздо'],b:['пидо','опиздо'],c:['ху','любо'],e:['ий','ый']},
    {a:['толстомелко'],b:['ху'],c:['пизд','хер'],e:['ий']},
    {a:['много','мало'],b:['пизд','мудо'],c:['',''],e:['ый','ий']},
    {a:['малоопиздо','мало'],b:['любо','пиздо'],c:['',''],e:['ый','ий']},
    {a:['пидо','свино'],b:['свино','блядo'],c:['рыл','грыз'],e:['ый','ий']},
    {a:['зло','низко'],b:['суче','мудо'],c:['ног','хер'],e:['ий','ый']},
    {a:['члено','пидо'],b:['сос','глот'],c:['',''],e:['ый','ий']},
    {a:['хуе','срако'],b:['срако','мудо'],c:['грыз','пизд'],e:['ый','истый']}
  ];
  const REF_COMPLEX_NOUN=[
    {a:['мудо','манда','блядo'],b:['манда','пидо'],c:['пизд','хуй'],e:['ник','арь']},
    {a:['суче','низко'],b:['долбо','пидо'],c:['ног','хер'],e:['ник','ец']},
    {a:['мандо','блядo','пидо'],b:['блядo','суче'],c:['гондон','пизд'],e:['ник','арь']},
    {a:['ебло','опиздо'],b:['опиздо','мало'],c:['хер','грыз'],e:['ник','арь']},
    {a:['пидо','свино'],b:['свино','блядo'],c:['рыл','грыз'],e:['ник','ец']},
    {a:['хуе','срако'],b:['срако','мудо'],c:['грыз','пизд'],e:['ник','ец']}
  ];
  const REF_COMPLEX_CACHE={dict:null};
  function compoundSourceData(){
    if(REF_COMPLEX_CACHE.dict) return REF_COMPLEX_CACHE;
    const nouns=[...(DB.male||[]),...(DB.female||[])].map(String);
    const adjs=[...(DB.adj||[])].map(String);
    REF_COMPLEX_CACHE.dict=new Set([...nouns,...adjs].map(x=>x.toLowerCase()));
    return REF_COMPLEX_CACHE;
  }
  function buildDynamicCompound(kind){
    const d=compoundSourceData();
    const models=kind==='adj'?REF_COMPLEX_ADJ:REF_COMPLEX_NOUN;
    for(let attempt=0;attempt<60;attempt++){
      const m=pickArr(models);
      const a=pickArr(m.a), b=pickArr(m.b), c=pickArr(m.c), e=pickArr(m.e);
      const result=(a+b+c+e).replace(/[^а-яё]/giu,'');
      if(result.length<8||result.length>34) continue;
      if(d.dict.has(result)) continue;
      if(/(?:аый|яый|ыый|оый|еый|йый|йий|йой|хуйый|хуйий|оий|ийий|ыйый|ойой)$/u.test(result)) continue;
      return result;
    }
    return kind==='adj'?'мудомандапиздый':'мудомандапиздник';
  }

  function generatedCompoundWord(kind,ctx){
    const freq=ctx.compoundFreq || (ctx.compoundFreq=new Map());
    const diversity=Number(document.querySelector('#diversity').value)/100;
    let best='',bestScore=Infinity;
    for(let i=0;i<16;i++){
      const candidate=buildDynamicCompound(kind);
      const f=freq.get(candidate)||0;
      // Повтор разрешён, но при высокой Diversity его стоимость выше.
      const score=f*(0.35+diversity*1.65)+Math.random()*0.7;
      if(score<bestScore){best=candidate;bestScore=score;}
      if(diversity>=.8 && f===0) return candidate;
      if(diversity<=.15 && i===0) return candidate;
    }
    return best;
  }

  function sanitizeCompound(w,kind){
    let x=String(w||'').toLowerCase();
    x=x.replace(/([аеёиоуыэюя])\1{2,}/gu,'$1$1');
    return x.length>32 ? x.slice(0,32) : x;
  }

  function compoundWordCount(text){
    return String(text||'').replace(/[!?.,:;]+$/u,'').trim().split(/\s+/u).filter(Boolean).length;
  }

  function compoundMinWords(compoundLength){
    // Составное слово считается одним словом независимо от того, сколько
    // морфем в него собрано. Поэтому длина фразы проверяется именно по
    // пробелам, а не по длине самого композита.
    if(compoundLength==='short') return 2;
    if(compoundLength==='medium') return 3;
    return 4; // long
  }

  function compoundPhrase(compoundLength){
    const g=(gender==='female'?'female':gender==='male'?'male':(chance(.5)?'female':'male'));
    const targetPrefix=target?`${target}, ты `:'';
    const kind=chance(.56)?'adj':'noun';
    const raw=generatedCompoundWord(kind,ctx);
    const safeRaw=sanitizeCompound(raw,kind);
    const c=kind==='adj'?compoundAdjectiveGender(safeRaw,g):compoundNounGender(safeRaw,g);
    ctx.compoundFreq = ctx.compoundFreq || new Map();
    ctx.compoundFreq.set(safeRaw,(ctx.compoundFreq.get(safeRaw)||0)+1);
    // 0.833-style length guard: составной режим не должен игнорировать
    // выбранную длину. Раньше при любом значении #length мог вернуться
    // одиночный композит: «хуедвупиздый!». Теперь сам композит остаётся
    // центром фразы, но вокруг него строится минимально соответствующая
    // выбранной длине конструкция.
    const pool=g==='female'?DB.female:DB.male;
    const depPool=g==='female'?DB.female:DB.male;
    const noun=pool[Math.floor(Math.random()*pool.length)];
    const dep=depPool[Math.floor(Math.random()*depPool.length)];
    const noun2=pool[Math.floor(Math.random()*pool.length)];
    const dep2=depPool[Math.floor(Math.random()*depPool.length)];

    if(compoundLength==='short'){
      // Короткая: минимум два содержательных слова.
      if(kind==='adj') return clean(`${targetPrefix}${c} ${noun}!`);
      const a=compoundAdjectiveGender(generatedCompoundWord('adj',ctx),g);
      return clean(`${targetPrefix}${a} ${c}!`);
    }

    if(compoundLength==='medium'){
      // Средняя: составное + именная группа из 3–5 слов.
      if(kind==='adj'){
        return clean(`${targetPrefix}${c} ${noun} ${genitiveNoun(dep,g)}!`);
      }
      const a=compoundAdjectiveGender(generatedCompoundWord('adj',ctx),g);
      return clean(`${targetPrefix}${a} ${c} ${genitiveNoun(dep,g)}!`);
    }

    // Длинная: составное слово не может быть всей генерацией; добавляем
    // вторую смысловую группу. Это намеренно разнообразнее, чем обязательное
    // тире: длинная форма может быть как цельной, так и с постпозиционной
    // группой, сохраняя старошкольную нерегулярность.
    if(kind==='adj'){
      if(chance(.55)) return clean(`${targetPrefix}${c} ${noun} ${genitiveNoun(dep,g)}, ${A(g)} ${noun2}!`);
      return clean(`${targetPrefix}${c} ${noun} ${genitiveNoun(dep,g)} — ${A(g)} ${noun2}!`);
    }
    const a=compoundAdjectiveGender(generatedCompoundWord('adj',ctx),g);
    if(chance(.55)) return clean(`${targetPrefix}${a} ${c} ${genitiveNoun(dep,g)}, ${A(g)} ${noun2} ${genitiveNoun(dep2,g)}!`);
    return clean(`${targetPrefix}${a} ${c} ${genitiveNoun(dep,g)} — ${A(g)} ${noun2}!`);
  }

  const ADV=[
    'безусловно','воистину','непременно','определённо','несомненно','разумеется',
    'безоговорочно','абсолютно','совершенно','категорически','однозначно','явно',
    'несомненно','неизменно','неуклонно','откровенно','искренне','прямо-таки',
    'поистине','истинно','впрямь','действительно','реально','вполне','весьма',
    'довольно','достаточно','чрезвычайно','необычайно','невероятно','невообразимо',
    'немыслимо','несусветно','непомерно','небывало','изрядно','крайне','особенно',
    'чуть-чуть','слегка','капельку','чуточку','малость','немного','немножко',
    'почти','едва ли','уж очень','в меру','не в меру','до безобразия',
    'до неприличия','подозрительно','необъяснимо','безнадёжно','непристойно', 'излишне',
    'чрезмерно','стопудово','на редкость','исключительно','прямо','настолько'
  ];

  // Словарные составные слова. Эта ветка используется только когда
  // пользователь включил «Составные слова».
  const compoundAwareChoose=(pool,key)=>choose(pool,used,ctx.words,diversity,ctx);
  const word=(pool,key)=>{
    const x=compoundAwareChoose(pool,key);
    used.add(x); ctx.words.add(x);
    ctx.freq=ctx.freq||new Map(); ctx.freq.set(x,(ctx.freq.get(x)||0)+1);
    return x;
  };
  const adv=()=>{
    const x=choose(ADV,used,ctx.advs,diversity,ctx);
    ctx.advs.add(x); used.add(x);
    ctx.freq=ctx.freq||new Map(); ctx.freq.set(x,(ctx.freq.get(x)||0)+1);
    return x;
  };

  // ---------------- Морфология ----------------
  // Словарь хранит существительные в именительном падеже.
  // Для конструкций типа «обожатель паразитов» нужен родительный.
  // Здесь используются продуктивные русские модели + несколько специальных
  // окончаний, характерных для словаря. Слово никогда не меняется, если
  // преобразование выглядит сомнительно.
  function genitiveNoun(word, nounGender){
    let w=String(word||'');
    if(!w) return w;
    if(GEN_SG_EXCEPT[w]) return GEN_SG_EXCEPT[w];
    if(nounGender==='female'){
      if(/ия$/u.test(w)) return w.replace(/ия$/u,'ии');
      if(/ея$/u.test(w)) return w.replace(/ея$/u,'еи');
      if(/ья$/u.test(w)) return w.replace(/ья$/u,'ьи');
      if(/[жшчщ]а$/u.test(w)) return w.replace(/а$/u,'и');
      if(/[гкх]а$/u.test(w)) return w.replace(/а$/u,'и');
      if(/я$/u.test(w)) return w.replace(/я$/u,'и');
      if(/а$/u.test(w)) return w.replace(/а$/u,'ы');
      if(/ь$/u.test(w)) return w.replace(/ь$/u,'и');
      return w;
    }
    if(/ец$/u.test(w)) return w.replace(/ец$/u,'ца');
    if(/ёнок$/u.test(w)) return w.replace(/ёнок$/u,'ёнка');
    if(/енок$/u.test(w)) return w.replace(/енок$/u,'енка');
    if(/онок$/u.test(w)) return w.replace(/онок$/u,'онка');
    if(/ёк$/u.test(w)) return w.replace(/ёк$/u,'ька');
    if(/ок$/u.test(w)) return w.replace(/ок$/u,'ка');
    if(/ей$/u.test(w)) return w.replace(/й$/u,'я');
    if(/ай$/u.test(w)) return w.replace(/й$/u,'я');
    if(/ой$/u.test(w)) return w.replace(/й$/u,'я');
    if(/ый$/u.test(w)) return w.replace(/ый$/u,'ого');
    if(/ий$/u.test(w)) return w.replace(/ий$/u,'его');
    if(/ой$/u.test(w)) return w.replace(/ой$/u,'ого');
    if(/ь$/u.test(w)) return w.replace(/ь$/u,'я');
    if(/й$/u.test(w)) return w.replace(/й$/u,'я');
    // «папа»-подобные мужские слова встречаются в словаре редко;
    // для них оставляем форму как есть, чтобы не получить явную ошибку.
    if(/[аеёиоуыэюя]$/u.test(w)) return w;
    return w+'а';
  }

  // Родительный множественного числа дополнительный вариант для
  // конструкций «обожатель / пожиратель / глотатель / ...».
  // Словарь хранит только именительный ед. числа, поэтому здесь используются
  // наиболее продуктивные модели и несколько важных исключений.
  const GEN_SG_EXCEPT={
    'пёздырь':'пёздыря','клещ':'клеща','петух':'петуха','ефрейтор':'ефрейтора',
    'жаба':'жабы','коала':'коалы','псяра':'псяры','лахудра':'лахудры',
    'курица':'курицы','морда':'морды','тупка':'тупки','чайка':'чайки',
    'белуга':'белуги','похотничка':'похотнички','поёботка':'поёботки'
  };
  const GEN_PL_EXCEPT={
    'комсомолец':'комсомольцев','жилец':'жильцов','удалец':'удальцов','молодец':'молодцов',
    'паразит':'паразитов','циклоп':'циклопов','ворон':'воронов','ворона':'ворон',
    'фурия':'фурий','писька':'писек','животное':'животных','животные':'животных',
    'енот':'енотов','паразитка':'паразиток','сучка':'сучек','жабры':'жабр','свинья':'свиней',
    'собака':'собак','коза':'коз','овца':'овец','лошадь':'лошадей','лошадка':'лошадок',
    'курва':'курв','блядь':'блядей','манда':'манд','пизда':'пизд','жопа':'жоп',
    'хуя':'хуёв','хуй':'хуёв','член':'членов','осёл':'ослов','петух':'петухов',
    'дегенерат':'дегенератов','кретин':'кретинов','идиот':'идиотов','мудак':'мудаков',
    'долбоёб':'долбоёбов','пидор':'пидоров','еблан':'ебланов','лох':'лохов',
    'енотик':'енотиков','хомяк':'хомяков','пеликан':'пеликанов','циклопик':'циклопиков',
    'бяка':'бяк','мандачня':'мандачней','чучундра':'чучундр','ссакунишка':'ссакунишек','пиздасоска':'пиздасосок','пиздотряска':'пиздотрясок'
  };
  // Множественный родительный больше не строится продуктивно.
  // Для него оставлены только формы, которые уже подтверждены словарём /
  // архивными примерами. Это сознательно консервативнее: лучше дать
  // родительный ед. числа, чем получить уродливое «кровопицов» из автоматики.
  function genitivePluralNoun(word, nounGender){
    const w=String(word||'');
    if(!w) return w;
    return GEN_PL_EXCEPT[w] || '';
  }

  function nounInfo(forceGender){
    const g=groupGender(forceGender);
    const pool=g==='female'?DB.female:DB.male;
    const chosen=word(pool,g==='female'?'female':'male');
    const isRole=GENITIVE_ROLE_MALE.has(chosen)||GENITIVE_ROLE_FEMALE.has(chosen);
    return {word:chosen,gender:g,target:false,isRole};
  }
  function targetInfo(){
    if(!target) return null;
    // Цель не склоняется и не определяет род окружающих слов.
    return {word:target,gender:groupGender(),target:true};
  }
  // Редкое внештатное слово: не держим «хуедвупиздый» в основном словаре,
  // но оставляем маленький шанс случайно получить его как прилагательное.
  // Это сохраняет слово как пасхалку, не позволяя ему забивать выдачу.
  const RARE_ADJ=['хуедвупиздый'];
  const adjective=(g)=>{
    if(chance(0.012) && !(diversity>=1 && ctx.words.has(RARE_ADJ[0]))){
      const base=choose(RARE_ADJ,used,ctx.words,diversity,ctx);
      used.add(base); ctx.words.add(base);
      return adjectiveForGender(base,g);
    }
    return adjectiveForGender(word(DB.adj,'adj'),g);
  };
  const A=(g,allowAdv=true)=>{
    const a=adjective(g);
    return allowAdv && chance(.34) ? adv()+' '+a : a;
  };
  const A2=(g)=>A(g,false);
  // Управляющие существительные. Важно: роль определяется лексически,
  // а не по случайному окончанию слова. Старый вариант с regex вроде /арь|ор|щик/
  // превращал «мусор», «пылесос» и множество обычных существительных в
  // управляющие слова и поэтому слишком часто порождал ложный родительный.
  const ROLE_MALE = new Set([
    'обожатель','пожиратель','почитатель','требователь','соблазнитель','притягатель',
    'глотатель','расхититель','раздиратель','сношатель','представитель','ломатель',
    'пономарь','пихальщик','дрочильщик','сосатель','сосальщик','лизатель',
    'вредитель','падальщик','очкодрал','очколиз','педрильник','пелоточник',
    'пукальщик','геморойщик','сральник','пиздотряс','пиздосос',
    'жопочник','жопотряс','жоподёр','мозгоебатель','мозгоёб'
  ]);
  const ROLE_FEMALE = new Set([
    'обожательница','пожирательница','почитательница','требовательница',
    'соблазнительница','притягательница','глотательница','расхитительница',
    'раздирательница','сношательница','представительница','пихальщица',
    'дрочильщица','сосальщица','вредительница','падальщица','пукальщица',
    'сральница','пиздососка','пиздотряска','жопососка','жопотряска','мозгоебательница','ломательница'
  ]);
  const roleNoun=(g)=>{
    g=groupGender(g);
    const pool=g==='female'?DB.female:DB.male;
    const roles=g==='female'?ROLE_FEMALE:ROLE_MALE;
    const candidates=pool.filter(w=>roles.has(w));
    // Ролевой слот НИКОГДА не подменяется обычным существительным.
    // Если свежие роли закончились, повторяем уже использованную роль.
    // Иначе схема «прилагательное + роль» незаметно превращается в
    // обычное «прилагательное + существительное».
    // Если словарь неожиданно не содержит ни одной роли, не подменяем
    // роль обычным существительным. Это явная ошибка данных, поэтому
    // безопаснее вернуть пустой слот, который будет отфильтрован/повторён
    // вызывающей конструкцией, чем silently сломать грамматический класс.
    if(!candidates.length) return {word:'',isRole:false};
    let source=candidates;
    if(candidates.length && diversity>=1){
      const freshRole=candidates.filter(w=>!ctx.words.has(w) && !used.has(w));
      if(freshRole.length) source=freshRole;
    }else if(candidates.length && diversity>=0.35){
      const freshRole=candidates.filter(w=>!ctx.words.has(w) && !used.has(w));
      if(freshRole.length && chance(0.82)) source=freshRole;
    }
    // Для специализированных role-слотов 50% не должен постоянно
    // возвращать одно и то же слово. Держим короткий cooldown последних
    // ролей, но не запрещаем повтор навсегда: это сохраняет рандом оригинала.
    ctx.roleRecent=ctx.roleRecent||[];
    if(diversity>=0.35 && diversity<1){
      const fresh=source.filter(w=>!ctx.roleRecent.includes(w) && !used.has(w));
      if(fresh.length) source=fresh;
      else {
        const notRecent=source.filter(w=>!ctx.roleRecent.includes(w));
        if(notRecent.length) source=notRecent;
      }
    }
    const chosen=word(source,'role');
    if(roles.has(chosen)){
      ctx.roleRecent.push(chosen);
      const keep=Math.max(3,Math.round(4+diversity*8));
      if(ctx.roleRecent.length>keep) ctx.roleRecent.splice(0,ctx.roleRecent.length-keep);
    }
    return {word:chosen,isRole:roles.has(chosen)};
  };
  function chooseCaseInfo(x, profile='free') {
    // Падеж выбирается не «для разнообразия», а по синтаксической роли.
    // В самостоятельной именной группе после тире существительное остаётся
    // в именительном: «— спизданутый вредитель», «— ожиревший мудотряс».
    // Родительный появляется только там, где его действительно требует
    // конструкция с управляющим существительным: «обожатель паразитов».
    if(profile==='roleObject'){
      // После слов типа «обожатель / глотатель / почитатель / дрочильщик»
      // зависимый объект всегда родительный. Чередуем ед. и мн. число,
      // но никогда не подставляем именительный только ради случайности.
      if(chance(.46)){
        const plural=genitivePluralNoun(x.word,x.gender);
        if(plural) return {word:plural,gender:x.gender,plural:true,grammaticalCase:'genPlural'};
      }
      return {word:genitiveNoun(x.word,x.gender),gender:x.gender,plural:false,grammaticalCase:'gen'};
    }
    // Самостоятельная группа: именительный. Отдельные свободные падежные
    // цепочки имеют собственные схемы s7–s9 и не должны протекать сюда.
    return {word:x.word,gender:x.gender,plural:false,grammaticalCase:'nom'};
  }
  function roleObjectNounInfo(g){
    // Объект не обязан иметь род управляющей роли: «требователь жоп»,
    // «глотатель ануса», «пожиратель енотов». Поэтому объект выбирается из
    // объединённого существительного словаря, а его род сохраняется отдельно
    // для правильного склонения.
    const pools=[...new Set(DB.male.concat(DB.female))];
    const roleWords=new Set([...ROLE_MALE,...ROLE_FEMALE]);
    const candidates=pools.filter(w=>!roleWords.has(w));
    const chosen=word(candidates,'roleObject');
    const gender=DB.female.includes(chosen)?'female':'male';
    return {word:chosen,gender,target:false};
  }
  const objectInfo=(g)=>chooseCaseInfo(roleObjectNounInfo(g),'roleObject');
  function adjectiveGenitive(base, nounGender, plural){
    let w=String(base||''); if(!w) return w;
    if(plural){
      const r=[[/вшийся$/u,'вшихся'],[/ившийся$/u,'ившихся'],[/ывшийся$/u,'ывшихся'],[/авшийся$/u,'авшихся'],[/евшийся$/u,'евшихся'],[/явшийся$/u,'явшихся'],[/ующийся$/u,'ующихся'],[/ающийся$/u,'ающихся'],[/яющийся$/u,'яющихся'],[/ущийся$/u,'ущихся'],[/ящийся$/u,'ящихся'],[/ющийся$/u,'ющихся'],[/вший$/u,'вших'],[/ивший$/u,'ивших'],[/ывший$/u,'ывших'],[/авший$/u,'авших'],[/евший$/u,'евших'],[/явший$/u,'явших'],[/ующий$/u,'ующих'],[/ающий$/u,'ающих'],[/яющий$/u,'яющих'],[/ущий$/u,'ущих'],[/ящий$/u,'ящих'],[/ющий$/u,'ющих'],[/ий$/u,'их'],[/ый$/u,'ых'],[/ой$/u,'ых']];
      for(const [rx,repl] of r) if(rx.test(w)) return w.replace(rx,repl); return w;
    }
    if(nounGender==='female'){
      const r=[[/вшийся$/u,'вшейся'],[/ившийся$/u,'ившейся'],[/ывшийся$/u,'ывшейся'],[/авшийся$/u,'авшейся'],[/евшийся$/u,'евшейся'],[/явшийся$/u,'явшейся'],[/ующийся$/u,'ующейся'],[/ающийся$/u,'ающейся'],[/яющийся$/u,'яющейся'],[/ущийся$/u,'ущейся'],[/ящийся$/u,'ящейся'],[/ющийся$/u,'ющейся'],[/вший$/u,'вшей'],[/ивший$/u,'ившей'],[/ывший$/u,'ывшей'],[/авший$/u,'авшей'],[/евший$/u,'евшей'],[/явший$/u,'явшей'],[/ующий$/u,'ующей'],[/ающий$/u,'ающей'],[/яющий$/u,'яющей'],[/ущий$/u,'ущей'],[/ящий$/u,'ящей'],[/ющий$/u,'ющей'],[/кий$/u,'кой'],[/гий$/u,'гой'],[/хий$/u,'хой'],[/ий$/u,'ей'],[/ый$/u,'ой'],[/ой$/u,'ой']];
      for(const [rx,repl] of r) if(rx.test(w)) return w.replace(rx,repl); return w;
    }
    const r=[[/вшийся$/u,'вшегося'],[/ившийся$/u,'ившегося'],[/ывшийся$/u,'ывшегося'],[/авшийся$/u,'авшегося'],[/евшийся$/u,'евшегося'],[/явшийся$/u,'явшегося'],[/ующийся$/u,'ующегося'],[/ающийся$/u,'ающегося'],[/яющийся$/u,'яющегося'],[/ущийся$/u,'ущегося'],[/ящийся$/u,'ящегося'],[/ющийся$/u,'ющегося'],[/вший$/u,'вшего'],[/ивший$/u,'ившего'],[/ывший$/u,'ывшего'],[/авший$/u,'авшего'],[/евший$/u,'евшего'],[/явший$/u,'явшего'],[/ующий$/u,'ующего'],[/ающий$/u,'ающего'],[/яющий$/u,'яющего'],[/ущий$/u,'ущего'],[/ящий$/u,'ящего'],[/ющий$/u,'ющего'],[/кий$/u,'кого'],[/гий$/u,'гого'],[/хий$/u,'хого'],[/ий$/u,'его'],[/ый$/u,'ого'],[/ой$/u,'ого']];
    for(const [rx,repl] of r) if(rx.test(w)) return w.replace(rx,repl); return w;
  }
  function dependentGroup(g){
    return chooseCaseInfo(nounInfo(g),'free');
  }
  function dependentGroupWithAdj(g){
    const x=dependentGroup(g);
    // Свободная именная группа всегда остаётся в именительном.
    // Склонение здесь намеренно не запускается.
    return adjective(x.gender)+' '+x.word;
  }
  // Родительный теперь разрешён только для ролей, у которых он действительно
  // выглядит как зависимый объект/адресат. Сам факт попадания слова в ROLE_*
  // больше НЕ означает «склони второе существительное». Это убирает цепочки
  // вроде «пиздотряска блядословки», «вредительница махновки»,
  // «пелоточник герантофила», которые технически строились старым алгоритмом,
  // но не давали характерной для оригинала связи.
  const GENITIVE_ROLE_MALE = new Set([
    // Только роли, для которых зависимый объект реально встречается в
    // архивных примерах/скриншотах: «пожиратель циклопов», «глотатель ануса»,
    // «раздиратель письки», «сношатель евнухов», «расхититель животных»,
    // «обожатель турков», «представитель енотов», а также редкие
    // «соблазнитель сучек», «притягатель киборгов», «ломатель хрюков» и т.п.
    'обожатель','пожиратель','почитатель','требователь','соблазнитель',
    'притягатель','глотатель','расхититель','раздиратель','сношатель',
    'представитель','ломатель','пихальщик','дрочильщик','сосатель','сосальщик','лизатель','вредитель','падальщик','мозгоебатель','мозгоёб'
  ]);
  const GENITIVE_ROLE_FEMALE = new Set([
    'обожательница','пожирательница','почитательница','требовательница',
    'соблазнительница','притягательница','глотательница','расхитительница',
    'раздирательница','сношательница','представительница','ломательница',
    'пихальщица','дрочильщица','сосальщица','вредительница','падальщица','мозгоебательница'
  ]);
  const rolePhraseForWord=(roleWord,g)=>{
    g=groupGender(g);
    const genRoles=g==='female'?GENITIVE_ROLE_FEMALE:GENITIVE_ROLE_MALE;
    if(!genRoles.has(roleWord)) return roleWord;
    const info=objectInfo(g);
    if(chance(.68)){
      const adj=adjectiveGenitive(word(DB.adj,'roleObjectAdj'),info.gender,info.plural);
      return roleWord+' '+adj+' '+info.word;
    }
    return roleWord+' '+info.word;
  };
  const rolePhrase=(g)=>{
    g=groupGender(g);
    const role=roleNoun(g);
    if(!role.isRole) return role.word;
    const genRoles=g==='female'?GENITIVE_ROLE_FEMALE:GENITIVE_ROLE_MALE;
    if(!genRoles.has(role.word)) return role.word;
    // Переходная роль должна быть завершена объектом.
    return rolePhraseForWord(role.word,g);
  };
  const roleWithAdj=(g)=>A2(g)+' '+rolePhrase(g);

  // Редкий «старошкольный» свободный блок: несколько именных групп,
  // затем инструментальный оборот и постпоставленное причастие.
  // В отличие от role-схем он не требует управляющего существительного.
  // Все существительные берутся из исходных словарей; меняется только падеж
  // там, где сама конструкция его требует.
  const ALL_NOUNS = DB.male.concat(DB.female);
  function freeNounInfo(){
    const w=word(ALL_NOUNS,'freeNoun');
    const g=DB.female.includes(w)?'female':'male';
    return {word:w,gender:g,target:false};
  }
  function instrumentalNoun(wordValue, nounGender){
    let w=String(wordValue||'');
    if(!w) return w;
    const EX={
      'петух':'петухом','хуй':'хуем','хуя':'хуем','член':'членом','осёл':'ослом',
      'ворон':'вороном','паразит':'паразитом','дегенерат':'дегенератом',
      'мудак':'мудаком','пидор':'пидором','долбоёб':'долбоёбом','еблан':'ебланом',
      'японец':'японцем','ефрейтор':'ефрейтором','африканец':'африканцем'
    };
    if(EX[w]) return EX[w];
    if(nounGender==='female'){
      if(/ия$/u.test(w)) return w.replace(/ия$/u,'ией');
      if(/ея$/u.test(w)) return w.replace(/ея$/u,'еей');
      if(/ья$/u.test(w)) return w.replace(/ья$/u,'ьёй');
      if(/ь$/u.test(w)) return w.replace(/ь$/u,'ью');
      if(/я$/u.test(w)) return w.replace(/я$/u,'ей');
      if(/а$/u.test(w)) return w.replace(/а$/u,'ой');
      return w;
    }
    if(/ец$/u.test(w)) return w.replace(/ец$/u,'цем');
    if(/ёнок$/u.test(w)) return w.replace(/ёнок$/u,'ёнком');
    if(/енок$/u.test(w)) return w.replace(/енок$/u,'енком');
    if(/онок$/u.test(w)) return w.replace(/онок$/u,'онком');
    if(/й$/u.test(w)) return w.replace(/й$/u,'ем');
    if(/ь$/u.test(w)) return w.replace(/ь$/u,'ем');
    if(/[жшчщц]$/u.test(w)) return w+'ем';
    if(/[бвгджзклмнпрстфх]$/u.test(w)) return w+'ом';
    return w;
  }
  function participle(g){
    const pool=DB.adj.filter(w=>/(вший|вшая|ющий|ящ|ивший|ывший|ший|нный|тый|тыйся|шийся|ющийся|ящийся)$/u.test(w));
    if(pool.length) return adjectiveForGender(word(pool,'participle'),g);
    return adjective(g);
  }

  let length=document.querySelector('#length').value;
  if(length==='random') length=pick(['short','medium','long']);

  // В архивных скриншотах начальное «—» / «, ты» это визуальный остаток
  // пустого поля обращения. В генераторной схеме тире имеет смысл только
  // В оригинале длинное «—» служит либо разделителем двух самостоятельных
  // групп, либо заменой пустого поля обращения. Короткие тире не используем.
  // ---------------- Scheme registry ----------------
  // Единый реестр метаданных используется только для реально активных
  // специализированных пулов: chaos/target/chaosTarget. Старый огромный
  // массив «schemes» был отдельной, больше не вызываемой системой и удалён.
  // Теперь schemePick получает характеристики конкретного пула по ID.
  // Специальные схемы режима «Хаос». В отличие от «Разное», здесь две
  // независимые именные группы получают род отдельно. Внутри каждой группы
  // согласование остаётся цельным, но левая и правая части намеренно могут
  // быть мужскими/женскими независимо друг от друга.
  const chaosSchemes=[
    {id:'c1',len:'short',f:()=>{const a=nounInfo(),b=nounInfo();return `${A(a.gender)} ${a.word} — ${A(b.gender)} ${b.word}!`; }},
    {id:'c2',len:'short',f:()=>{const a=nounInfo(),b=nounInfo();return `${A(a.gender)} ${a.word} — ${A(b.gender)} ${rolePhrase(b.gender)}!`; }},
    {id:'c3',len:'short',f:()=>{const a=nounInfo(),b=nounInfo();return `${emptyAddressPrefix()}${A(a.gender)} ${a.word} — ${A(b.gender)} ${b.word}!`; }},
    {id:'c4',len:'medium',f:()=>{const a=nounInfo(),b=nounInfo();return `${A(a.gender)} ${A2(a.gender)} ${a.word} — ${A2(b.gender)} ${b.word}!`; }},
    {id:'c5',len:'medium',f:()=>{const a=nounInfo(),b=nounInfo();return `${A(a.gender)} ${a.word} — ${A2(b.gender)} ${rolePhrase(b.gender)}!`; }},
    {id:'c6',len:'medium',f:()=>{const a=nounInfo(),b=nounInfo();return `${emptyAddressPrefix()}${A(a.gender)} ${rolePhrase(a.gender)} — ${A(b.gender)} ${b.word}!`; }},
    {id:'c7',len:'long',f:()=>{const a=nounInfo(),b=nounInfo();return `${A(a.gender)}, ${A2(a.gender)} ${a.word} — ${A2(b.gender)}, ${A2(b.gender)} и ${A2(b.gender)} ${b.word}!`; }},
    {id:'c8',len:'long',f:()=>{const a=nounInfo(),b=nounInfo();return `${A(a.gender)} ${a.word} — ${adv()} ${A2(b.gender)} ${rolePhrase(b.gender)}!`; }},
    {id:'c9',len:'long',f:()=>{const a=nounInfo(),b=nounInfo();return `${emptyAddressPrefix()}${adv()} ${A(a.gender)} ${a.word} — ${A2(b.gender)}, ${A2(b.gender)} и ${rolePhrase(b.gender)}!`; }},
    {id:'c10',len:'long',f:()=>{const a=nounInfo(),b=nounInfo();return `${A(a.gender)} ${rolePhrase(a.gender)} — ${A2(b.gender)} ${b.word}, ${A2(b.gender)} и ${A2(b.gender)} ${nounInfo(b.gender).word}!`; }}
  ];
  const ti=targetInfo();
  const addressedTarget = target ? target : '';
  // В оригинале при пустом поле «Кого обругать?» интерфейс мог показывать
  // длинное «—» перед самостоятельной группой. Это не падеж и не часть
  // словосочетания: это именно пустое обращение. Используем его редко и только
  // в адресных схемах без заданной цели.
  const emptyAddressPrefix=()=> '— ';
  // Цель больше не привязана к началу строки. В оригинальном генераторе
  // имя могло быть первым словом, хвостом первой группы перед «—» или
  // частью второй группы. Поэтому здесь несколько независимых позиций:
  // начало / после определения / конец первой группы / начало второй группы /
  // конец второй группы. Важно: «, ты» оставляем только для настоящего
  // обращения; в остальных схемах имя ведёт себя как обычный якорь группы.

  const chaosTargetSchemes = target ? [
    {id:'ct1',len:'short',f:()=>{const a=nounInfo(),b=nounInfo();return `${addressedTarget}, ты ${A(a.gender)} ${a.word} — ${A(b.gender)} ${b.word}!`; }},
    {id:'ct2',len:'medium',f:()=>{const a=nounInfo(),b=nounInfo();return `${A(a.gender)} ${addressedTarget} — ${A2(b.gender)} ${rolePhrase(b.gender)}!`; }},
    {id:'ct3',len:'medium',f:()=>{const a=nounInfo(),b=nounInfo();return `${addressedTarget} — ${A(a.gender)} ${a.word}, ${A2(b.gender)} ${b.word}!`; }},
    {id:'ct4',len:'long',f:()=>{const a=nounInfo(),b=nounInfo();return `${A(a.gender)} ${a.word} ${addressedTarget} — ${adv()} ${A2(b.gender)} ${rolePhrase(b.gender)}!`; }},
    {id:'ct5',len:'long',f:()=>{const a=nounInfo(),b=nounInfo();return `${addressedTarget}, ты ${A(a.gender)}, ${A2(a.gender)} ${a.word} — ${A2(b.gender)} ${b.word}!`; }},
    {id:'ct6',len:'long',f:()=>{const a=nounInfo(),b=nounInfo();return `${A(a.gender)} ${rolePhrase(a.gender)} — ${addressedTarget}, ${A2(b.gender)} ${b.word}!`; }}
  ] : [];

  const targetSchemes = target ? [
    // Классическое обращение — сохраняем как наиболее частый вариант.
    {id:'t1',len:'short',f:()=>`${addressedTarget}, ты ${A(ti.gender)} ${A2(ti.gender)} ${nounInfo(ti.gender).word}!`},
    {id:'t2',len:'short',f:()=>`${addressedTarget}, ты ${A(ti.gender)} ${nounInfo(ti.gender).word}!`},
    {id:'t3',len:'short',f:()=>`${addressedTarget}, ты ${rolePhrase(ti.gender)}!`},

    // Имя после определения: «шутовской Серёжа — ...».
    {id:'t12',len:'short',f:()=>`${A(ti.gender)} ${addressedTarget}!`},
    {id:'t13',len:'short',f:()=>`${A(ti.gender)} ${A2(ti.gender)} ${addressedTarget}!`},
    {id:'t14',len:'short',f:()=>`${A(ti.gender)} ${addressedTarget} — ${A(ti.gender)} ${nounInfo(ti.gender).word}!`},
    {id:'t15',len:'short',f:()=>`${addressedTarget} — ${A(ti.gender)} ${nounInfo(ti.gender).word}!`},
    {id:'t16',len:'short',f:()=>`${A(ti.gender)} ${nounInfo(ti.gender).word} — ${addressedTarget}!`},

    {id:'t4',len:'medium',f:()=>`${addressedTarget}, ты ${A(ti.gender)}, ${A2(ti.gender)} и ${A2(ti.gender)} ${nounInfo(ti.gender).word}!`},
    {id:'t5',len:'medium',f:()=>`${addressedTarget}, ты ${A(ti.gender)} ${A2(ti.gender)} ${nounInfo(ti.gender).word}, ${rolePhrase(ti.gender)}!`},
    {id:'t6',len:'medium',f:()=>`${addressedTarget}, ты ${A(ti.gender)} ${A2(ti.gender)} ${rolePhrase(ti.gender)}!`},

    // Цель в конце первой группы — один из характерных для оригинала
    // вариантов: «[описание] имя — [вторая группа]».
    {id:'t17',len:'medium',f:()=>`${A(ti.gender)} ${A2(ti.gender)} ${addressedTarget} — ${A2(ti.gender)} ${nounInfo(ti.gender).word}!`},
    {id:'t18',len:'medium',f:()=>`${A(ti.gender)} ${rolePhrase(ti.gender)} ${addressedTarget} — ${A(ti.gender)} ${nounInfo(ti.gender).word}!`},
    {id:'t19',len:'medium',f:()=>`${A(ti.gender)} ${nounInfo(ti.gender).word} ${addressedTarget} — ${A2(ti.gender)} ${rolePhrase(ti.gender)}!`},
    {id:'t20',len:'medium',f:()=>`${A(ti.gender)} ${addressedTarget} — ${A2(ti.gender)} ${rolePhrase(ti.gender)}!`},

    {id:'t7',len:'long',f:()=>`${addressedTarget}, ты ${adv()} ${A2(ti.gender)}, ${A2(ti.gender)} и ${A2(ti.gender)} ${nounInfo(ti.gender).word}!`},
    {id:'t8',len:'long',f:()=>`${addressedTarget}, ты ${A(ti.gender)}, ${A2(ti.gender)} и ${A2(ti.gender)} ${nounInfo(ti.gender).word}!`},
    {id:'t9',len:'long',f:()=>`${addressedTarget}, ты ${A(ti.gender)} ${nounInfo(ti.gender).word} ${rolePhrase(ti.gender)}!`},

    // Цель как часть правой группы.
    {id:'t21',len:'long',f:()=>`${A(ti.gender)} ${nounInfo(ti.gender).word} — ${A2(ti.gender)} ${addressedTarget}!`},
    {id:'t22',len:'long',f:()=>`${A(ti.gender)} ${nounInfo(ti.gender).word} — ${A2(ti.gender)} ${rolePhrase(ti.gender)} ${addressedTarget}!`},
    {id:'t23',len:'long',f:()=>`${A(ti.gender)} ${A2(ti.gender)} ${addressedTarget} — ${adv()} ${A2(ti.gender)} ${nounInfo(ti.gender).word}!`},
    {id:'t24',len:'long',f:()=>`${A(ti.gender)} ${rolePhrase(ti.gender)} ${addressedTarget} — ${A2(ti.gender)}, ${A2(ti.gender)} и ${A2(ti.gender)} ${nounInfo(ti.gender).word}!`},
    {id:'t25',len:'long',f:()=>`${A(ti.gender)} ${nounInfo(ti.gender).word} — ${addressedTarget}, ${adv()} ${A2(ti.gender)} ${rolePhrase(ti.gender)}!`},
    {id:'t26',len:'long',f:()=>`${adv()} ${A(ti.gender)} ${addressedTarget} — ${A2(ti.gender)} и ${A2(ti.gender)} ${rolePhrase(ti.gender)}!`},
    // Дополнительные позиции цели. Здесь имя не превращается в «слово для
    // морфологии»: оно остаётся буквально введённым пользователем.
    {id:'t27',len:'medium',f:()=>`${rolePhrase(ti.gender)} ${addressedTarget}!`},
    {id:'t28',len:'medium',f:()=>`${A(ti.gender)} ${rolePhrase(ti.gender)} — ${addressedTarget}!`},
    {id:'t29',len:'medium',f:()=>`${A(ti.gender)} ${nounInfo(ti.gender).word} — ${addressedTarget}, ты ${rolePhrase(ti.gender)}!`},
    {id:'t30',len:'medium',f:()=>`${A(ti.gender)} ${addressedTarget}, ты ${nounInfo(ti.gender).word} — ${rolePhrase(ti.gender)}!`},
    {id:'t31',len:'long',f:()=>`${addressedTarget} — ${A(ti.gender)}, ${A2(ti.gender)} ${nounInfo(ti.gender).word} и ${rolePhrase(ti.gender)}!`},
    {id:'t32',len:'long',f:()=>`${A(ti.gender)} ${nounInfo(ti.gender).word} ${addressedTarget} — ${adv()} ${A2(ti.gender)} ${rolePhrase(ti.gender)}!`},
    {id:'t33',len:'long',f:()=>`${A(ti.gender)} ${rolePhrase(ti.gender)} — ${addressedTarget}, ${A2(ti.gender)} ${nounInfo(ti.gender).word}!`},
    {id:'t34',len:'long',f:()=>`${A(ti.gender)} ${A2(ti.gender)} ${nounInfo(ti.gender).word} — ${rolePhrase(ti.gender)}, ${addressedTarget}!`}
  ] : [];

  // ---------------- Construction grammar / old-school balance ----------------
  // Базовая архитектура остаётся конструкционной: сначала выбирается тип
  // высказывания, затем его группы и только после этого слова. При этом
  // распределение специально сдвинуто в сторону старой манеры damn.ru:
  // простая именная группа, цепочка определений, тире между двумя группами,
  // управляющее слово с зависимым существительным. Новые алгоритмы
  // diversity/coverage/морфологии продолжают работать внутри этих классов.
  // 0.833 OLD-SCHOOL DAMN LAYER
  // В старой манере важен не «красивый» русский текст, а ощущение случайно
  // склеенных словарных блоков: короткая именная группа, два независимых
  // определения, тире между несвязанными группами, роль + объект, а иногда
  // намеренно абсурдная падежная связка. Этот слой ставится перед обычной
  // construction-грамматикой и не меняет сам словарь.
  function oldSchoolPhraseRaw(L){
    const pickN=()=>nounInfo();
    const gN=(g)=>nounInfo(g);
    const simple=(g)=>{const n=gN(g); return `${A(n.gender,false)} ${n.word}`;};
    const double=(g)=>{const n=gN(g); return `${A(n.gender,false)}, ${A2(n.gender)} ${n.word}`;};
    const triple=(g)=>{const n=gN(g); return `${A(n.gender,false)}, ${A2(n.gender)} и ${A2(n.gender)} ${n.word}`;};
    const role=(g)=>rolePhrase(g);
    const dash=(a,b)=>clean(`${a} — ${b}!`);
    const a=pickN(), b=pickN();

    if(L==='short'){
      const r=Math.random();
      if(r<.20) return clean(`${simple(a.gender)}!`);
      if(r<.34) return clean(`${double(a.gender)}!`);
      if(r<.46) return clean(`${role(a.gender)}!`);
      if(r<.58) return dash(simple(a.gender),simple(b.gender));
      if(r<.68) return dash(simple(a.gender),role(b.gender));
      if(r<.77) return dash(a.word,simple(b.gender));
      if(r<.87) return clean(`${role(a.gender)} ${genitiveNoun(b.word,b.gender)}!`);
      if(r<.94) return clean(`${A(a.gender,false)} ${a.word} ${genitiveNoun(b.word,b.gender)}!`);
      return clean(`${a.word} — ${A(b.gender,false)} ${b.word}!`);
    }

    if(L==='medium'){
      const r=Math.random();
      if(r<.13) return clean(`${double(a.gender)}!`);
      if(r<.24) return clean(`${triple(a.gender)}!`);
      if(r<.34) return clean(`${role(a.gender)} ${genitiveNoun(b.word,b.gender)}!`);
      if(r<.45) return dash(simple(a.gender),double(b.gender));
      if(r<.55) return dash(double(a.gender),simple(b.gender));
      if(r<.65) return dash(role(a.gender),simple(b.gender));
      if(r<.74) return dash(simple(a.gender),role(b.gender));
      if(r<.82) return clean(`${adv()} ${simple(a.gender)}!`);
      if(r<.90) return clean(`${A(a.gender,false)} ${a.word} ${genitiveNoun(b.word,b.gender)} — ${A2(b.gender)} ${b.word}!`);
      return clean(`${a.word}, ${A(a.gender,false)} ${role(a.gender)} — ${A2(b.gender)} ${b.word}!`);
    }

    const r=Math.random();
    if(r<.12) return clean(`${triple(a.gender)}!`);
    if(r<.22) return clean(`${adv()} ${double(a.gender)}!`);
    if(r<.32) return dash(triple(a.gender),simple(b.gender));
    if(r<.42) return dash(simple(a.gender),triple(b.gender));
    if(r<.52) return dash(role(a.gender),double(b.gender));
    if(r<.61) return dash(double(a.gender),role(b.gender));
    if(r<.70) return clean(`${role(a.gender)} ${genitiveNoun(b.word,b.gender)} — ${A2(b.gender)} ${b.word}!`);
    if(r<.79) return clean(`${triple(a.gender)} — ${adv()} ${role(b.gender)}!`);
    if(r<.88) return clean(`${adv()} ${role(a.gender)} — ${double(b.gender)}!`);
    if(r<.94) return clean(`${a.word} ${genitiveNoun(b.word,b.gender)} ${participle(a.gender)}!`);
    return clean(`${simple(a.gender)} — ${double(b.gender)}, ${A2(b.gender)} и ${A2(b.gender)} ${b.word}!`);
  }

  // 0.900 EXPERIMENTAL OLD SCHOOL ENGINE
  // Не заменяет Classic: это отдельный пробный слой. Мужской/женский/смешанный/
  // хаос остаются прежними; меняется только способ сборки фразы.
  function oldSchoolExperimentalPhraseRaw(L){
    // 0.914: упрощённая грамматика в духе старого damn.ru.
    // Без составного слова фраза должна выглядеть как обычная короткая
    // конструкция; безумие создаётся сочетанием слов, усилителей и 1 ударной
    // составной лексемы, а не сложной грамматикой.
    const g = chaos ? groupGender() : gender;
    const n = nounInfo(g), n2 = nounInfo(g), n3 = nounInfo(g);
    const targetWord = (typeof target !== 'undefined' && target) ? String(target).trim() : '';
    const useComp = document.querySelector('#compoundMode')?.checked;
    const compChance = useComp ? (L==='short' ? .07 : L==='medium' ? .11 : .16) : 0;
    const comp = ()=>{
      const kind = chance(.72) ? 'adj' : 'noun';
      const raw = generatedCompoundWord(kind,ctx);
      const safe = sanitizeCompound(raw,kind);
      ctx.compoundFreq = ctx.compoundFreq || new Map();
      ctx.compoundFreq.set(safe,(ctx.compoundFreq.get(safe)||0)+1);
      return kind==='adj' ? compoundAdjectiveGender(safe,g) : compoundNounGender(safe,g);
    };
    const Aold = ()=> (Math.random()<compChance ? comp() : A(g,false));
    const Aold2 = ()=> (Math.random()<(compChance*.72) ? comp() : A2(g));
    const ad = ()=>adv();
    const role = ()=>rolePhrase(g);
    const finish = x=>clean(x.endsWith('!')?x:x+'!');
    const nameVariants = body => {
      if(!target) return body;
      const forms = [
        `${target}, ты ${body}`,
        `${target} — ${body}`,
        `${body} ${target}`,
        `${body} — ${target}`,
        `${target}, ${body}`
      ];
      return forms[Math.floor(Math.random()*forms.length)];
    };
    const simple = ()=>`${Aold()} ${n.word}`;
    const double = ()=>`${Aold()}, ${Aold2()} ${n.word}`;
    const triple = ()=>`${Aold()}, ${Aold2()} и ${Aold2()} ${n.word}`;
    const dashSimple = ()=>`${simple()} — ${simple()}`;
    const dashDouble = ()=>`${simple()} — ${double()}`;
    const addressed = ()=> target ? `${target}, ты ${Aold()} ${n.word}` : `${Aold()} ${n.word}`;

    if(L==='short'){
      const r=Math.random();
      if(r<.22) return finish(nameVariants(simple()));
      if(r<.39) return finish(nameVariants(double()));
      if(r<.52) return finish(nameVariants(role()));
      if(r<.64) return finish(nameVariants(`${ad()} ${simple()}`));
      if(r<.75) return finish(nameVariants(dashSimple()));
      if(r<.86) return finish(nameVariants(`${Aold()} ${role()}`));
      return finish(nameVariants(`${n.word} — ${Aold2()} ${n2.word}`));
    }

    if(L==='medium'){
      const r=Math.random();
      if(r<.20) return finish(nameVariants(double()));
      if(r<.35) return finish(nameVariants(triple()));
      if(r<.47) return finish(nameVariants(`${ad()} ${double()}`));
      if(r<.59) return finish(nameVariants(`${Aold()} ${role()}`));
      if(r<.70) return finish(nameVariants(dashDouble()));
      if(r<.81) return finish(nameVariants(`${double()} — ${Aold2()} ${n2.word}`));
      if(r<.90) return finish(nameVariants(`${role()} — ${Aold()} ${n2.word}`));
      return finish(nameVariants(addressed()));
    }

    const r=Math.random();
    if(r<.20) return finish(nameVariants(triple()));
    if(r<.32) return finish(nameVariants(`${ad()} ${triple()}`));
    if(r<.43) return finish(nameVariants(`${ad()} ${double()}`));
    if(r<.55) return finish(nameVariants(`${triple()} — ${simple()}`));
    if(r<.66) return finish(nameVariants(`${simple()} — ${triple()}`));
    if(r<.76) return finish(nameVariants(`${double()} — ${double()}`));
    if(r<.85) return finish(nameVariants(`${role()} — ${triple()}`));
    if(r<.92) return finish(nameVariants(`${ad()} ${role()} — ${double()}`));
    return finish(nameVariants(`${triple()} ${role()}`));
  }

  function constructionPhraseRaw(){
    const L=length;

    // 0.833: основная масса обычных генераций идёт через старую
    // конструкционную манеру; специализированные target/chaos/compound
    // ветки остаются отдельными. Чем короче фраза, тем выше доля старого
    // простого рисунка; длинные получают больше тире и составных групп.
    const oldChance = L==='short' ? .72 : (L==='medium' ? .68 : .64);
    if(chance(oldChance)) return oldSchoolPhraseRaw(L);

    // Style balance 0.828: простые группы теперь заметно чаще, тире — реже,
    // а «свободные» старошкольные конструкции получили отдельный небольшой
    // шанс. Цель — не сделать грамматику строже, а убрать ощущение матрицы.
    const rareChance = L==='long' ? .095 : (L==='medium' ? .075 : .06);
    if(chance(rareChance)){
      const a=nounInfo();
      const r=Math.random();
      if(r<.34){
        const b=freeNounInfo();
        const c=freeNounInfo();
        const dep=genitivePluralNoun(b.word,b.gender)||genitiveNoun(b.word,b.gender);
        return clean(`${a.word} ${dep} ${instrumentalNoun(c.word,c.gender)} ${participle(a.gender)}!`);
      }
      if(r<.58) return clean(`${adv()} ${participle(a.gender)} ${a.word}!`);
      if(r<.78) return clean(`${a.word}, ${participle(a.gender)}!`);
      if(r<.90){
        const b=freeNounInfo();
        return clean(`${a.word} ${genitiveNoun(b.word,b.gender)}!`);
      }
      return clean(`${participle(a.gender)} ${a.word}, ${participle(a.gender)}!`);
    }

    const group=(g,mode)=>{
      const x=nounInfo(g);
      const nounText=GENITIVE_ROLE_MALE.has(x.word)||GENITIVE_ROLE_FEMALE.has(x.word) ? rolePhraseForWord(x.word,x.gender) : x.word;
      if(mode==='noun') return nounText;
      if(mode==='aN') return `${A(x.gender,false)} ${nounText}`;
      if(mode==='advAN') return `${adv()} ${A(x.gender,false)} ${nounText}`;
      if(mode==='aaN') return `${A(x.gender,false)}, ${A2(x.gender)} ${nounText}`;
      if(mode==='aaaN') return `${A(x.gender,false)}, ${A2(x.gender)} и ${A2(x.gender)} ${nounText}`;
      if(mode==='a2N') return `${A(x.gender,false)} ${A2(x.gender)} ${nounText}`;
      if(mode==='role') return rolePhrase(x.gender);
      if(mode==='aRole') return `${A(x.gender,false)} ${rolePhrase(x.gender)}`;
      if(mode==='advRole') return `${adv()} ${A(x.gender,false)} ${rolePhrase(x.gender)}`;
      return `${A(x.gender,false)} ${x.word}`;
    };

    const dash=(left,right)=>clean(`${left} — ${right}!`);

    if(L==='short'){
      const r=Math.random();
      if(r<.27) return clean(`${group(undefined,'aN')}!`);
      if(r<.39) return clean(`${group(undefined,'noun')}!`);
      if(r<.50) return clean(`${group(undefined,'aRole')}!`);
      if(r<.59){ const a=nounInfo(); return dash(group(a.gender,'noun'),group(a.gender,'aN')); }
      if(r<.67){ const a=nounInfo(); return dash(group(a.gender,'aN'),group(a.gender,'noun')); }
      if(r<.75){ const a=nounInfo(); return dash(group(a.gender,'aN'),group(a.gender,'aN')); }
      if(r<.84) return clean(`${group(undefined,'advAN')}!`);
      if(r<.92){ const a=nounInfo(); return dash(group(a.gender,'noun'),group(a.gender,'role')); }
      return clean(`${group(undefined,'role')}!`);
    }

    if(L==='medium'){
      const r=Math.random();
      if(r<.18) return clean(`${group(undefined,'aN')}!`);
      if(r<.31) return clean(`${group(undefined,'a2N')}!`);
      if(r<.43) return clean(`${group(undefined,'aRole')}!`);
      if(r<.53) return clean(`${group(undefined,'advAN')}!`);
      if(r<.61){ const a=nounInfo(); return dash(group(a.gender,'aN'),group(a.gender,'aN')); }
      if(r<.69){ const a=nounInfo(); return dash(group(a.gender,'noun'),group(a.gender,'aRole')); }
      if(r<.76){ const a=nounInfo(); return dash(group(a.gender,'aN'),group(a.gender,'role')); }
      if(r<.83) return clean(`${group(undefined,'aaaN')}!`);
      if(r<.91) return clean(`${group(undefined,'role')}!`);
      return clean(`${group(undefined,'noun')}!`);
    }

    // Long: длинные цепочки остаются, но не доминируют над короткими группами.
    {
      const r=Math.random();
      if(r<.16) return clean(`${group(undefined,'aaaN')}!`);
      if(r<.27) return clean(`${adv()} ${group(undefined,'aN')}!`);
      if(r<.38) return clean(`${group(undefined,'a2N')}!`);
      if(r<.49){ const a=nounInfo(); return dash(group(a.gender,'aN'),group(a.gender,'aaaN')); }
      if(r<.58){ const a=nounInfo(); return dash(group(a.gender,'aaaN'),group(a.gender,'aN')); }
      if(r<.66){ const a=nounInfo(); return dash(group(a.gender,'aN'),group(a.gender,'aRole')); }
      if(r<.73){ const a=nounInfo(); return dash(group(a.gender,'noun'),group(a.gender,'role')); }
      if(r<.82) return clean(`${group(undefined,'advRole')}!`);
      if(r<.89){
        const x=nounInfo();
        return clean(`${adv()} ${A(x.gender,false)}, ${A2(x.gender)} и ${A2(x.gender)} ${x.word}!`);
      }
      return clean(`${group(undefined,'aRole')}!`);
    }
  }

  function chaosLoosePhrase(){
    const g1=groupGender();
    const g2=groupGender();
    const n1=nounInfo(g1), n2=nounInfo(g2);
    const mode=Math.random();
    if(mode<.24) return clean(`${A(g1,false)} ${n1.word}!`);
    if(mode<.40) return clean(`${n1.word}!`);
    if(mode<.56) return clean(`${A(g1,false)} ${rolePhrase(g1)}!`);
    if(mode<.70) return clean(`${adv()} ${A(g1,false)} ${n1.word}!`);
    if(mode<.84) return clean(`${A(g1,false)}, ${A2(g1)} и ${A2(g1)} ${n1.word}!`);
    return clean(`${A(g1,false)} ${n1.word}, ${A2(g2)} ${n2.word}!`);
  }

  function constructionFamily(text){
    const t=String(text||'');
    if(/ — /.test(t)){
      if(/ — [^!]*\b(пожиратель|глотатель|требователь|обожатель|расхититель|раздиратель|сношатель|представитель|ломатель|соблазнитель)/u.test(t)) return 'dash-role';
      if(/ — /.test(t) && (t.match(/ — /g)||[]).length===1) return 'dash';
    }
    if(/, [^!]+ и [^!]+ [^!]+!$/.test(t)) return 'chain';
    if(/^— /.test(t)) return 'address';
    if(/\b(пожиратель|глотатель|требователь|обожатель|расхититель|раздиратель|сношатель|представитель|ломатель|соблазнитель)(?:ница)?\b/u.test(t)) return 'role';
    if(/, [^!]+!$/.test(t)) return 'post';
    if(/^[^ ]+ [^ ]+ [^ ]+!$/.test(t)) return 'triple';
    if(/^[^ ]+ [^ ]+!$/.test(t)) return 'aN';
    return 'noun';
  }
  function constructionPhrase(){
    // Повторяем только при совпадении семейства конструкции. Слова по-прежнему
    // выбираются прежним механизмом diversity, поэтому мы не меняем его работу.
    for(let i=0;i<7;i++){
      const out=constructionPhraseRaw();
      const fam=constructionFamily(out);
      if(!ctx.schemes.has('base:'+fam) || diversity<0.55){
        ctx.schemes.add('base:'+fam);
        return out;
      }
    }
    const out=constructionPhraseRaw();
    ctx.schemes.add('base:'+constructionFamily(out));
    return out;
  }

  // Галочка включает составные конструкции поверх обычного движка.
  // При выключенной галочке путь генерации ниже не изменяется.
  if(compoundEnabled && chance(.08)){
    // Жёсткий предохранитель: составной композит никогда не может
    // «съесть» всю фразу и выдать один токен при medium/long.
    const minWords=compoundMinWords(length);
    let cp='';
    for(let attempt=0; attempt<8; attempt++){
      cp=compoundPhrase(length);
      if(compoundWordCount(cp)>=minWords) break;
    }

    // Теоретически недостижимый fallback оставляем простым и гарантированно
    // соответствующим длине. Он нужен на случай будущих изменений compoundPhrase.
    if(compoundWordCount(cp)<minWords){
      const g=(gender==='female'?'female':gender==='male'?'male':(chance(.5)?'female':'male'));
      const pool=g==='female'?DB.female:DB.male;
      const a=adjectiveForGender(pick(DB.adj),g);
      const n1=pick(pool), n2=pick(pool), n3=pick(pool);
      if(length==='short') cp=clean(`${a} ${n1}!`);
      else if(length==='medium') cp=clean(`${a} ${n1} ${genitiveNoun(n2,g)}!`);
      else cp=clean(`${a} ${n1} ${genitiveNoun(n2,g)} — ${a} ${n3}!`);
    }
    ctx.schemes.add('compound:'+constructionFamily(cp));
    if(target){
      const tw=String(target).trim();
      if(tw && !String(cp).toLocaleLowerCase().includes(tw.toLocaleLowerCase())){
        const core=String(cp).replace(/!\s*$/,'').trim();
        const variants=[`${tw}, ты ${core}`,`${tw} — ${core}`,`${core}, ${tw}`,`${tw}: ${core}`];
        cp=clean(variants[Math.floor(Math.random()*variants.length)]+'!');
      }
    }
    return cp;
  }

  // 0.833: общая проверка длины применяется не только к составным,
  // но и к обычным/target/chaos схемам. В старой версии medium/long могли
  // выбрать короткую схему из-за общей конструкции, поэтому «Средние» иногда
  // давали 1–2 слова, а «Длинные» — 2–3.
  const phraseWordCount = text => String(text||'').replace(/[!?.,:;]+$/u,'').trim().split(/\s+/u).filter(Boolean).length;
  const minPhraseWords = L => L==='short' ? 2 : (L==='medium' ? 3 : 4);
  function ensurePhraseLength(out,L){
    const min=minPhraseWords(L);
    if(phraseWordCount(out)>=min) return out;
    for(let attempt=0;attempt<10;attempt++){
      const retry=constructionPhraseRaw();
      if(phraseWordCount(retry)>=min) return retry;
    }
    const g=chaos ? groupGender() : gender;
    const n1=nounInfo(g), n2=nounInfo(g), n3=nounInfo(g);
    if(L==='short') return clean(`${A(g,false)} ${n1.word}!`);
    if(L==='medium') return clean(`${A(g,false)} ${n1.word} ${genitiveNoun(n2.word,g)}!`);
    return clean(`${A(g,false)}, ${A2(g)} ${n1.word} и ${A2(g)} ${n2.word} ${genitiveNoun(n3.word,g)}!`);
  }

  // 0.900 UNIFIED ENGINE
  // Один движок объединяет старые конструкционные схемы и Old School-слой.
  // Режимы мужской/женский/смешанный/хаос остаются параметрами одного и того же
  // генератора, а не отдельными генераторами.
  let out='';
  const oldWeight = length==='short' ? .72 : (length==='medium' ? .68 : .64);
  if(chaos && !target && chance(.22)) out=chaosLoosePhrase();
  else if(chance(oldWeight)) out=oldSchoolExperimentalPhraseRaw(length);
  else {
    const sourceSchemes = chaos ? (target ? chaosTargetSchemes : chaosSchemes) : (target ? targetSchemes : null);
    if(!sourceSchemes) out=constructionPhrase();
    else {
      let pool=sourceSchemes.filter(s=>s.len===length);
      if(!pool.length) pool=sourceSchemes;
      const scheme=schemePick(pool,target ? (chaos?'chaosTarget':'target') : (chaos?'chaos':'base'),ctx,diversity);
      ctx.schemes.add(scheme.id);
      out=clean(scheme.f());
    }
  }

  // Имя/цель — обязательная часть каждой фразы, если пользователь его задал.
  if(target){
    const tw=String(target).trim();
    if(tw && !String(out).toLocaleLowerCase().includes(tw.toLocaleLowerCase())){
      const core=String(out).replace(/!\s*$/,'').trim();
      const variants=[`${tw}, ты ${core}`,`${tw} — ${core}`,`${core}, ${tw}`,`${tw}: ${core}`];
      out=clean(variants[Math.floor(Math.random()*variants.length)]+'!');
    }
  }
  out=ensurePhraseLength(out,length);
  if(target){
    const tw=String(target).trim();
    if(tw && !String(out).toLocaleLowerCase().includes(tw.toLocaleLowerCase())){
      const core=String(out).replace(/!\s*$/,'').trim();
      const variants=[`${tw}, ты ${core}`,`${tw} — ${core}`,`${core}, ${tw}`,`${tw}: ${core}`];
      out=clean(variants[Math.floor(Math.random()*variants.length)]+'!');
    }
  }
  return out;
}
function malePhrase(){ return makePhrase('male'); }
function femalePhrase(){ return makePhrase('female'); }

function phrase(batchCtx){
  return chance(.5) ? makePhrase('male',batchCtx) : makePhrase('female',batchCtx);
}

let results=[];

function generateText(options={}){
  if(options && typeof options==='object'){
    Object.assign(runtimeSettings, options);
    if(options.words != null) runtimeSettings.textWords=options.words;
    if(options.gender != null) runtimeSettings.textGender=options.gender;
    if(options.paragraphs != null) runtimeSettings.textParagraphs=options.paragraphs;
    if(options.targetFreq != null) runtimeSettings.textTargetFreq=options.targetFreq;
  }
  const wordsTarget=Math.max(50,Math.min(5000,Math.floor(Number(runtimeSettings.textWords))||500));
  const freq=runtimeSettings.textTargetFreq;
  const textGender=runtimeSettings.textGender;
  const paraMode=runtimeSettings.textParagraphs;
  const targetClean=targetWordValue();
  const targetParts=targetClean ? targetClean.split(/\s+/).filter(Boolean) : [];
  const ctx={words:new Set(),schemes:new Set(),advs:new Set(),freq:new Map(),roleRecent:[],compoundFreq:new Map()};
  const chunks=[]; let wordCount=0; let chunksSinceTarget=0; let targetInsertedEarly=false;
  let failedFits=0; const maxFailedFits=24;
  const targetEveryChunks=freq==='often'?3:(freq==='rare'?7:Infinity);
  const addTarget=()=>{
    if(!targetParts.length || wordCount+targetParts.length>wordsTarget) return false;
    chunks.push(targetParts.slice()); wordCount+=targetParts.length; chunksSinceTarget=0; return true;
  };
  const fallbackWord=()=>{
    const g=(textGender==='mixed'||textGender==='chaos')?(chance(.5)?'male':'female'):textGender;
    const pool=g==='female'?DB.female:DB.male;
    return pool[Math.floor(Math.random()*pool.length)];
  };
  while(wordCount<wordsTarget){
    const remaining=wordsTarget-wordCount;
    if(remaining===1){ chunks.push([fallbackWord()]); wordCount++; break; }
    let chunk='';
    try{
      if(textGender==='chaos') chunk=makePhrase('chaos',ctx,false);
      else if(textGender==='mixed') chunk=makePhrase(chance(.5)?'male':'female',ctx,false);
      else chunk=makePhrase(textGender,ctx,false);
    }catch(e){ chunk=''; }
    const parts=String(chunk||'').trim().split(/\s+/).filter(Boolean);
    if(!parts.length || parts.length>remaining){
      failedFits++;
      if(failedFits>=maxFailedFits){ chunks.push([fallbackWord()]); wordCount++; failedFits=0; }
      continue;
    }
    chunks.push(parts); wordCount+=parts.length; failedFits=0; chunksSinceTarget++;
    if(targetParts.length && freq!=='none' && !targetInsertedEarly){ if(addTarget()) targetInsertedEarly=true; }
    else if(targetParts.length && freq!=='none' && chunksSinceTarget>=targetEveryChunks) addTarget();
  }
  let text=chunks.map(x=>x.join(' ')).join(' ').replace(/\s+/g,' ').trim();
  if(text && !/[.!?]$/.test(text)) text+='.';
  if(paraMode!=='one'){
    const count=paraMode==='three'?3:5;
    const base=Math.floor(chunks.length/count), extra=chunks.length%count;
    const paras=[]; let pos=0;
    for(let i=0;i<count;i++){
      const take=base+(i<extra?1:0);
      const part=chunks.slice(pos,pos+take).map(x=>x.join(' ')).join(' ').trim();
      if(part) paras.push(part); pos+=take;
    }
    text=paras.join('\n\n');
  }
  return text;
}

function generateBatch(options={}){
  Object.assign(runtimeSettings, options);
  const count=Math.max(1,Math.min(200,Math.floor(Number(options.count))||20));
  const mode=options.mode || 'mixed';
  const ctx={words:new Set(),schemes:new Set(),advs:new Set(),freq:new Map(),roleRecent:[],compoundFreq:new Map()};
  const out=[]; const seen=new Set();
  const d=Number(runtimeSettings.diversity)/100;
  const repeatChance=.20-(.16*d);
  for(let i=0;i<count;i++){
    let x='', tries=0;
    do { x=makePhrase(mode==='mixed'?(chance(.5)?'male':'female'):mode,ctx); tries++; }
    while(seen.has(x) && tries<8 && Math.random()>repeatChance);
    seen.add(x); out.push(x);
  }
  return out;
}

export { DB, runtimeSettings, generateBatch, generateText, makePhrase };
export function setSettings(options={}){ Object.assign(runtimeSettings, options); return runtimeSettings; }

// ===== Telegram / Cloudflare Workers adapter =====
// Settings are persisted in Cloudflare KV when BOT_SETTINGS is bound.
// Without KV the in-memory fallback still works, but settings can reset on cold starts.
const userSettings = new Map();
const warnedMissingKV = new Set();
const warnedKVRead = new Set();
const warnedKVWrite = new Set();
const DEFAULT_SETTINGS = {
  mode:'mixed', count:5, diversity:50, compoundMode:true,
  length:'random', targetWord:'', awaitingTarget:false, menu:'main'
};

function normalizeSettings(raw){
  const x={...defaultSettings(),...(raw&&typeof raw==='object'?raw:{})};
  x.mode=['male','female','mixed','chaos'].includes(x.mode)?x.mode:'mixed';
  x.count=Math.max(1,Math.min(100,Number(x.count)||5));
  x.diversity=Math.max(0,Math.min(100,Number(x.diversity)||0));
  x.compoundMode=x.compoundMode!==false;
  x.length=x.length||'random';
  x.targetWord=String(x.targetWord||'').slice(0,100);
  x.awaitingTarget=Boolean(x.awaitingTarget);
  x.menu=['main','settings','mode','count','diversity','target'].includes(x.menu)?x.menu:'main';
  return x;
}
function defaultSettings(){ return {...DEFAULT_SETTINGS}; }

async function settingsFor(env,chatId){
  const id=String(chatId);
  if(userSettings.has(id)) return userSettings.get(id);
  let saved=null;
  if(env.BOT_SETTINGS){
    try{
      saved=await env.BOT_SETTINGS.get(`settings:${id}`,'json');
    }catch(e){
      if(!warnedKVRead.has(id)){
        warnedKVRead.add(id);
        console.error('BOT_SETTINGS KV read failed; using temporary settings:',e?.message||e);
      }
    }
  }else if(!warnedMissingKV.has(id)){
    warnedMissingKV.add(id);
    console.error('BOT_SETTINGS KV binding is not configured; settings are temporary');
  }
  const s=normalizeSettings(saved);
  userSettings.set(id,s);
  return s;
}
async function saveSettings(env,chatId,s){
  const id=String(chatId);
  const clean=normalizeSettings(s);
  userSettings.set(id,clean);
  if(env.BOT_SETTINGS){
    try{
      await env.BOT_SETTINGS.put(`settings:${id}`,JSON.stringify(clean));
    }catch(e){
      if(!warnedKVWrite.has(id)){
        warnedKVWrite.add(id);
        console.error('BOT_SETTINGS KV write failed; keeping temporary settings:',e?.message||e);
      }
    }
  }else if(!warnedMissingKV.has(id)){
    warnedMissingKV.add(id);
    console.error('BOT_SETTINGS KV binding is not configured; settings are temporary');
  }
  return clean;
}
async function tg(env, method, body){
  const token=String(env.BOT_TOKEN||'').trim();
  if(!token) throw new Error('BOT_TOKEN is not configured');
  const r=await fetch(`https://api.telegram.org/bot${token}/${method}`,{
    method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)
  });
  const raw=await r.text();
  let data;
  try{ data=JSON.parse(raw); }
  catch(_){ throw new Error(`Telegram ${method}: HTTP ${r.status}, invalid JSON response`); }
  if(!r.ok || data?.ok!==true){
    const code=data?.error_code ?? r.status;
    const desc=data?.description || 'unknown Telegram API error';
    console.error(`Telegram API error in ${method}: ${code} ${desc}`);
    throw new Error(`Telegram API ${method}: ${code} ${desc}`);
  }
  return data;
}

