function keyboard(s){ return settingsReplyKeyboard(s); }

async function sendMenu(env,chatId,extra=''){
  const s=await settingsFor(env,chatId);
  s.menu='main'; s.awaitingTarget=false;
  const name=s.targetWord||'не задано';
  return tg(env,'sendMessage',{chat_id:chatId,text:`Генератор Мата 0.922\n\nРежим: ${s.mode}\nФраз: ${s.count}\nРазнообразие: ${s.diversity}%\nСоставные: ${s.compoundMode?'включены':'выключены'}\nИмя: ${name}${extra?'\n\n'+extra:''}`,reply_markup:mainReplyKeyboard()});
}

async function sendSettingsMenu(env,chatId,extra=''){
  const s=await settingsFor(env,chatId);
  s.menu='settings'; s.awaitingTarget=false;
  return tg(env,'sendMessage',{chat_id:chatId,text:`Настройки\n\nРежим: ${s.mode}\nФраз: ${s.count}\nРазнообразие: ${s.diversity}%\nСоставные: ${s.compoundMode?'включены':'выключены'}\nИмя: ${s.targetWord||'не задано'}${extra?'\n\n'+extra:''}`,reply_markup:settingsReplyKeyboard(s)});
}

async function generateTextFor(env,chatId){
  const s=await settingsFor(env,chatId);
  try{
    setSettings({diversity:s.diversity,compoundMode:s.compoundMode,textGender:s.mode});
    const text=generateText({words:500,gender:s.mode,paragraphs:'one',targetFreq:'rare'});
    return tg(env,'sendMessage',{chat_id:chatId,text:String(text).slice(0,3900),reply_markup:replyKeyboard()});
  }catch(e){
    console.error('text generation error',e);
    return tg(env,'sendMessage',{chat_id:chatId,text:`Ошибка генерации текста: ${e?.message||e}`,reply_markup:replyKeyboard()});
  }
}

async function askName(env,chatId){
  const s=await settingsFor(env,chatId);
  s.awaitingTarget=true; s.menu='target';
  await saveSettings(env,chatId,s);
  return tg(env,'sendMessage',{chat_id:chatId,text:'Введи имя или слово того, кого нужно обматерить.\n\nНапример: Вадим\n\nДля отмены нажми «◀️ НАЗАД» или /start.',reply_markup:targetReplyKeyboard()});
}

async function clearName(env,chatId){
  const s=await settingsFor(env,chatId);
  s.targetWord=''; s.awaitingTarget=false;
  await saveSettings(env,chatId,s);
  return sendMenu(env,chatId,'Имя удалено.');
}

function helpText(){
  return `Генератор Мата 0.922\n\n/start — открыть главное меню\n/generate — сгенерировать\n/generate 10 — сгенерировать указанное количество\n/settings — настройки\n/help — помощь\n/status — состояние настроек`;
}

async function setupBotMenu(env){
  await tg(env,'setMyCommands',{commands:[
    {command:'start',description:'Открыть главное меню'},
    {command:'generate',description:'Сгенерировать'},
    {command:'settings',description:'Настройки'},
    {command:'help',description:'Помощь'},
    {command:'status',description:'Состояние настроек'}
  ]});
  await tg(env,'setMyDescription',{description:'Генератор Мата 0.922. Нажми /start, чтобы открыть меню и начать работу.'});
}

function splitTelegramText(text,max=3900){
  const out=[];
  let rest=String(text||'');
  while(rest.length>max){
    let cut=rest.lastIndexOf('\n',max);
    if(cut<500) cut=rest.lastIndexOf(' ',max);
    if(cut<500) cut=max;
    out.push(rest.slice(0,cut));
    rest=rest.slice(cut).replace(/^\s+/,'');
  }
  if(rest) out.push(rest);
  return out;
}

async function generateFor(env,chatId,countOverride){
  let s;
  try{
    s=await settingsFor(env,chatId);
  }catch(e){
    console.error('settings load error:',e?.stack||e);
    return tg(env,'sendMessage',{chat_id:chatId,text:`Ошибка сохранения настроек: ${e?.message||e}`,reply_markup:mainReplyKeyboard()});
  }
  const count=Math.max(1,Math.min(100,Number(countOverride)||s.count));
  try{
    setSettings({
      diversity:s.diversity,
      compoundMode:s.compoundMode,
      length:s.length,
      targetWord:s.targetWord
    });

    const out=generateBatch({
      count,
      mode:s.mode,
      diversity:s.diversity,
      compoundMode:s.compoundMode,
      length:s.length,
      targetWord:s.targetWord
    });

    const text=out.map((x,i)=>`${i+1}. ${x}`).join('\n');
    for(const chunk of splitTelegramText(text)){
      await tg(env,'sendMessage',{
        chat_id:chatId,
        text:chunk,
        reply_markup:mainReplyKeyboard()
      });
    }
  }catch(e){
    console.error('generation error:',e?.stack||e);
    await tg(env,'sendMessage',{
      chat_id:chatId,
      text:`Ошибка генерации: ${e?.message||e}`,
      reply_markup:mainReplyKeyboard()
    });
  }
}

async function handleUpdate(update,env){
  if(update.callback_query){
    // Backward compatibility with any old inline-button message still in the chat.
    const q=update.callback_query; const chatId=q.message?.chat?.id;
    if(!chatId) return;
    await tg(env,'answerCallbackQuery',{callback_query_id:q.id});
    const s=await settingsFor(env,chatId); const d=q.data||'';
    if(d==='settings') return sendSettingsMenu(env,chatId);
    if(d==='name') return askName(env,chatId);
    if(d==='compound'){s.compoundMode=!s.compoundMode; await saveSettings(env,chatId,s); return sendSettingsMenu(env,chatId);}
    if(d==='generate') return generateFor(env,chatId);
    if(d.startsWith('setmode:')){s.mode=d.slice(8); await saveSettings(env,chatId,s); return sendSettingsMenu(env,chatId);}
    if(d.startsWith('setcount:')){s.count=Math.max(1,Math.min(100,Number(d.slice(9))||5)); await saveSettings(env,chatId,s); return sendSettingsMenu(env,chatId);}
    if(d.startsWith('setdiv:')){s.diversity=Math.max(0,Math.min(100,Number(d.slice(7))||0)); await saveSettings(env,chatId,s); return sendSettingsMenu(env,chatId);}
    return;
  }

  const m=update.message; if(!m||!m.chat) return;
  const chatId=m.chat.id; const text=String(m.text||'').trim();
  const s=await settingsFor(env,chatId);

  if(s.awaitingTarget){
    if(text==='◀️ НАЗАД'){
      s.awaitingTarget=false;
      await saveSettings(env,chatId,s);
      return sendSettingsMenu(env,chatId);
    }
    if(text==='/start'){
      s.awaitingTarget=false;
      await saveSettings(env,chatId,s);
      return sendMenu(env,chatId,'Выбери действие кнопками внизу.');
    }
    // Never store a bot menu button as the target name.
    const controlTexts=new Set([
      '🖕 СГЕНЕРИРОВАТЬ','⚙️ НАСТРОЙКИ','👤 КОГО ОБМАТЕРИТЬ','🧹 УБРАТЬ ЦЕЛЬ','/help',
      '🎛 РЕЖИМ: '+s.mode, '🔢 КОЛИЧЕСТВО: '+s.count,
      '🌈 РАЗНООБРАЗИЕ: '+s.diversity+'%', `🧩 СОСТАВНЫЕ: ${s.compoundMode?'ВКЛ':'ВЫКЛ'}`,
      `👤 КОГО ОБМАТЕРИТЬ: ${s.targetWord||'не задано'}`
    ]);
    if(!controlTexts.has(text) && !['♂️ Мужской','♀️ Женский','⚖️ Смешанный','☠️ Хаос','1','5','10','20','50','100','0%','25%','50%','75%','100%'].includes(text)){
      s.targetWord=text.slice(0,100); s.awaitingTarget=false;
      await saveSettings(env,chatId,s);
      return sendSettingsMenu(env,chatId,`Имя установлено: ${s.targetWord}`);
    }
    s.awaitingTarget=false;
    await saveSettings(env,chatId,s);
  }

  if(text==='/start') return sendMenu(env,chatId,'Выбери действие кнопками внизу.');
  if(text==='/help') return tg(env,'sendMessage',{chat_id:chatId,text:helpText(),reply_markup:mainReplyKeyboard()});
  if(text==='/status'){
    const storage=env.BOT_SETTINGS?'KV: подключено':'KV: НЕ ПОДКЛЮЧЕНО (настройки временные)';
    return tg(env,'sendMessage',{chat_id:chatId,text:`Хранилище настроек: ${storage}\nРежим: ${s.mode}\nФраз: ${s.count}\nРазнообразие: ${s.diversity}%\nСоставные: ${s.compoundMode?'включены':'выключены'}\nИмя: ${s.targetWord||'не задано'}`,reply_markup:mainReplyKeyboard()});
  }
  if(text==='/settings' || text==='⚙️ НАСТРОЙКИ') return sendSettingsMenu(env,chatId);
  if(text==='/generate' || text==='🖕 СГЕНЕРИРОВАТЬ') return generateFor(env,chatId);
  if(text==='👤 КОГО ОБМАТЕРИТЬ' || text.startsWith('👤 КОГО ОБМАТЕРИТЬ:')) return askName(env,chatId);
  if(text==='🧹 УБРАТЬ ЦЕЛЬ') return clearName(env,chatId);
  if(text==='◀️ НАЗАД'){
    if(s.menu==='mode' || s.menu==='count' || s.menu==='diversity') return sendSettingsMenu(env,chatId);
    if(s.menu==='target') return sendSettingsMenu(env,chatId);
    return sendMenu(env,chatId);
  }

  if(text==='🎛 РЕЖИМ: '+s.mode || text==='🎛 РЕЖИМ:') { s.menu='mode'; await saveSettings(env,chatId,s); return tg(env,'sendMessage',{chat_id:chatId,text:'Выбери режим:',reply_markup:modeReplyKeyboard()}); }
  if(text.startsWith('🎛 РЕЖИМ:')) { s.menu='mode'; await saveSettings(env,chatId,s); return tg(env,'sendMessage',{chat_id:chatId,text:'Выбери режим:',reply_markup:modeReplyKeyboard()}); }
  if(text.startsWith('🔢 КОЛИЧЕСТВО:')) { s.menu='count'; await saveSettings(env,chatId,s); return tg(env,'sendMessage',{chat_id:chatId,text:'Выбери количество фраз:',reply_markup:countReplyKeyboard()}); }
  if(text.startsWith('🌈 РАЗНООБРАЗИЕ:')) { s.menu='diversity'; await saveSettings(env,chatId,s); return tg(env,'sendMessage',{chat_id:chatId,text:'Выбери разнообразие:',reply_markup:diversityReplyKeyboard()}); }
  if(text.startsWith('🧩 СОСТАВНЫЕ:')){
    s.compoundMode=!s.compoundMode; await saveSettings(env,chatId,s); return sendSettingsMenu(env,chatId);
  }

  if(['♂️ Мужской','♀️ Женский','⚖️ Смешанный','☠️ Хаос'].includes(text)){
    s.mode={'♂️ Мужской':'male','♀️ Женский':'female','⚖️ Смешанный':'mixed','☠️ Хаос':'chaos'}[text];
    await saveSettings(env,chatId,s); return sendSettingsMenu(env,chatId);
  }
  if(['1','5','10','20','50','100'].includes(text)){
    s.count=Number(text); await saveSettings(env,chatId,s); return sendSettingsMenu(env,chatId);
  }
  if(['0%','25%','50%','75%','100%'].includes(text)){
    s.diversity=Number(text.slice(0,-1)); await saveSettings(env,chatId,s); return sendSettingsMenu(env,chatId);
  }

  if(text.startsWith('/generate')){
    const n=text.split(/\s+/)[1]; return generateFor(env,chatId,n);
  }
  return tg(env,'sendMessage',{chat_id:chatId,text:'Нажми /start, чтобы открыть меню.',reply_markup:mainReplyKeyboard()});
}

export default {
  async fetch(request, env){
    if(request.method==='GET') return new Response('Генератор Мата 0.922: OK');
    if(request.method!=='POST') return new Response('Method Not Allowed',{status:405});
    if(!env.BOT_TOKEN) return new Response('BOT_TOKEN is not configured',{status:500});
    const secret=env.WEBHOOK_SECRET;
    if(secret && request.headers.get('X-Telegram-Bot-Api-Secret-Token')!==secret) return new Response('Forbidden',{status:403});
    try{
      const update=await request.json();
      await handleUpdate(update,env);
      return new Response('OK');
    }catch(e){
      console.error('Telegram webhook error:',e?.stack||e);
      return new Response('Webhook error',{status:500});
    }
  }
};
